// The Gangho, part two: life in every city and stronghold on the map, inns and ferries, escorts,
// wandering heroes, chivalry and what it costs, famous names met in passing and tavern rumours; plus
// history's edges: lead-ups, aftermaths and the other worlds that exist when history is averted.
// Templates at the bottom give every location its own events (city life, taverns, gates, ferries).
import { E, O, C, R, P, M, Q, L, LATER } from './kit.js';
import { template } from '../../engine/registry.js';

// ── Hand-written: the Gangho ──────────────────────────────────────────
const GANGHO = [
  // Chang’an
  E('gh_changan_horse_fair', 'jianghu', { if: { loc: 'changan', age: [14, 65] }, once: false, cd: 5, art: 'market', title: 'The horse fair', text: 'The autumn horse fair fills the Western Market with dust and shouting. A trader from beyond the Jade Gate swears his grey mare can outrun the wind, and offers a wager to anyone who thinks otherwise.', choices: [
    P('Bet against the mare', 0.45, O('The mare outran the wind, two court horses and a dog. You paid up and bought the trader a drink out of respect.', { wealth: -6, charm: 1 }), O('The mare stopped halfway to eat a melon. The trader paid you, cursing in three languages.', { wealth: 12 })),
    R('Judge the horses for a nervous buyer', 'insight', 24, O('You pointed out a cracked hoof and a painted-over scar. The buyer paid you a fee and the dealer a visit.', { wealth: 5, rep: { merchants: 2 } }), O('You recommended a fine black stallion. It bit the buyer. The buyer blamed you, reasonably.', { charm: -1 })),
    C('Just watch', O('You watched the horses run until sunset, and smelled of horse for three days.', { sanity: 3 })),
  ] }),
  E('gh_changan_old_house', 'jianghu', { if: { loc: 'changan', age: [16, 50], stat: { body: '>=18' } }, art: 'feast', title: 'Old money', text: 'A noble house of Chang’an, all lacquer and debt, hires you to stand behind the master’s chair at a banquet and look like a famous swordsman. “Do not speak,” the steward says. “Famous swordsmen never speak.”', choices: [
    R('Look dangerous all evening', 'sanity', 45, O('You did not blink for four hours. Two creditors left early. The master paid you double and called you “Sword Ghost of the West,” which a poet wrote down.', { wealth: 15, fame: 2 }), O('You sneezed into the soup. The illusion collapsed. So did the master’s credit.', { wealth: 4, charm: -1 })),
    C('Speak anyway', O('A guest asked your sect. You told the truth. The master did not pay you, but the guest, a merchant’s widow, hired you herself the next day.', { wealth: 6, rep: { merchants: 2 } })),
  ] }),

  // Luoyang
  E('gh_luoyang_petition', 'jianghu', { if: { loc: 'luoyang', age: [15, 80] }, art: 'city', title: 'The petitioner', text: 'Outside the Murim Alliance hall a widow has knelt for nine days. A disciple of a great sect killed her son in a drunken duel, and the Alliance clerks keep losing her petition.', choices: [
    R('Carry her petition in yourself', 'fame', 22, O('You walked in, slapped the petition on the clerk’s desk and refused to leave. The disciple was confined to his sect for a year. It was not justice. It was more than she had.', { fame: 3, rep: { orthodox: -3 }, sanity: 3 }), O('The clerk had you thrown out on the steps beside her. She shared her rice with you.', { rep: { orthodox: -2 }, sanity: 1 })),
    Q('Pay a scribe to rewrite it properly (5 taels)', { stat: { wealth: '>=5' } }, O('A good scribe, the right seals, a copy to every sect. The Alliance had to answer it. The answer was a fine, paid in silver. She threw it in the river.', { wealth: -5, fame: 1 })),
    C('Walk past, like everyone', O('You walked past, like everyone. The Alliance hall has very clean steps; people kneel on them often.', { sanity: -3 })),
  ] }),
  E('gh_luoyang_peonies', 'jianghu', { if: { loc: 'luoyang', age: [14, 40], season: 0 }, once: false, cd: 4, danger: true, art: 'garden', title: 'Peony season', text: 'Luoyang in peony season. In the flower gardens a young master in purple silk has decided that the bench you are sitting on is his, and so is the view.', choices: [
    C('Give him the bench', O('You gave him the bench. He looked faintly disappointed; arrogance needs an audience to push against.', { sanity: -1 })),
    R('Make him laugh instead', 'charm', 26, O('You complimented his robe so lavishly he could not tell if you were mocking him. He sat next to you to find out. By evening you were drinking together.', { charm: 2, rep: { families: 2 } }), O('He decided you were mocking him, which was true.', { combat: { foe: { name: 'the young master in purple', kind: 'brawler', rel: 0 }, context: 'duel', lethal: 0.05, win: { text: 'He landed in the peonies. His servants pulled him out and glared at you all the way home.', fame: 2, rep: { families: -2 } }, lose: { text: 'You landed in the peonies. The gardener charged you for them.', wealth: -3 } } })),
    C('Challenge him to a peony-naming contest', O('He knew forty-one varieties. You knew six and invented eleven. He never noticed.', { insight: 1, charm: 1 })),
  ] }),

  // Kaifeng
  E('gh_kaifeng_thousand_ears', 'jianghu', { if: { loc: 'kaifeng', age: [16, 70], alive: 'madam_yeon' }, art: 'night', title: 'The Thousand Ears Pavilion', text: 'Madam Yeon receives you on the top floor of the Thousand Ears Pavilion, behind a screen painted with listening rabbits. “Everyone comes here to buy,” she says. “What are you selling?”', choices: [
    Q('Buy a secret about the coming years (30 taels)', { stat: { wealth: '>=30' } }, O('She named a date and a roof: winter of year twenty-three, the Namgung patriarch’s study. “Contracts are public, to the right people,” she said, and counted your silver twice.', { wealth: -30, meet: '@madam_yeon', codex: 'timeline.namgung_assassination' }), { show: { year: [12, 22] } }),
    R('Sell her something true', 'insight', 28, O('You told her which sect’s elders were quietly selling their lands. She paid you well, and wrote your name in a small book.', { wealth: 15, meet: '@madam_yeon', rel: { '@madam_yeon': { res: 10 } }, rep: { merchants: 2 } }), O('She already knew it. She already knew most things. She laughed, and let you go for free, which felt like being robbed.', { meet: '@madam_yeon', charm: -1 })),
    C('Ask what she knows about you', O('She read you a page about yourself. It was accurate, unflattering and included your shoe size. “Free sample,” she said.', { meet: '@madam_yeon', sanity: -2, insight: 1 })),
  ] }),
  E('gh_kaifeng_canal_strike', 'jianghu', { if: { loc: 'kaifeng', age: [16, 60] }, once: false, cd: 6, art: 'river', text: 'The canal porters of Kaifeng have stopped work. The guild master has hired toughs to break the strike, and the toughs are hiring anyone who can swing a stick.', choices: [
    C('Stand with the porters', O('You stood at the bridge with the porters. The toughs looked at you, did their sums and went to lunch. The guild master raised wages by a copper.', { fame: 2, rep: { merchants: -3 } })),
    C('Take the toughs’ money', O('Two taels to stand behind a man who was paid five. You did not hit anyone. You did not stop anyone being hit either.', { wealth: 2, infamy: 1, sanity: -3 })),
    R('Talk the guild master into a deal', 'charm', 32, O('You talked for an afternoon. The porters got their copper and the guild master got to say it was his idea. Everyone hated you a little, which is how you know it was fair.', { charm: 1, rep: { merchants: 2 }, fame: 1 }), O('The guild master listened politely and hired more toughs.')),
  ] }),

  // Wuchang
  E('gh_wuchang_crane_tower', 'jianghu', { if: { loc: 'wuchang', age: [14, 80] }, art: 'river', title: 'Yellow Crane Tower', text: 'Poets gather at the Yellow Crane Tower to write verses on its walls. An old scholar is weeping because someone has written a better poem than his directly above it.', choices: [
    R('Write one of your own', 'insight', 30, O('You wrote four lines about a crane that never came back. The old scholar stopped weeping long enough to hate you instead. By evening it was being copied in teahouses.', { fame: 3, insight: 1 }), O('You wrote four lines. A child corrected your rhyme.', { charm: -1 })),
    C('Comfort the old scholar', O('You told him his poem was the more honest of the two. He wiped his eyes and bought you fish. “Honest,” he said, “is what they call the worse one.”', { sanity: 3 })),
  ] }),
  E('gh_wuchang_flood_tide', 'jianghu', { if: { loc: 'wuchang', age: [14, 60], season: 1 }, once: false, cd: 5, danger: true, art: 'flood', text: 'Summer rains, and the Great River comes up the harbour steps. A grain barge has broken its moorings and is drifting toward the Han ferry, crowded with people.', choices: [
    R('Jump onto the barge and steer it off', 'body', 30, O('You leapt from roof to mast to barge and leaned on the sweep until your arms cracked. The barge missed the ferry by an arm’s length. The ferry cheered all the way across.', { fame: 4, health: -5 }), O('You leapt, slipped and went into the river. The barge hit the ferry. Everyone swam; you swam worst.', { health: -15, fame: 1 })),
    C('Shout the ferry back to shore', O('You and a dozen others shouted until the ferryman understood. He poled back, swearing. The barge hit the empty pier instead.', { fame: 1 })),
  ] }),

  // Chengdu
  E('gh_chengdu_hotpot', 'jianghu', { if: { loc: 'chengdu', age: [12, 80] }, once: false, cd: 4, art: 'inn', title: 'Nine Hells Hot Pot', text: 'A Chengdu hot pot house has a challenge painted on its wall: finish a bowl of the Nine Hells broth and eat free for a year. The wall beside it lists those who tried. It is a long wall.', choices: [
    R('Accept the challenge', 'body', 28, O('You finished it. Your soul left your body briefly and came back on fire. The owner painted your name in gold and fed you free all year.', { fame: 2, health: -4, wealth: 6 }), O('You made it to the third hell. The owner painted your name in very small letters.', { health: -6, charm: -1 })),
    C('Order the mild one', O('The mild one was hotter than anything in Guanzhong. You cried, and it was delicious.', { wealth: -1, health: 2, sanity: 2 })),
  ] }),
  E('gh_chengdu_brocade_thief', 'jianghu', { if: { loc: 'chengdu', age: [15, 60] }, art: 'market', title: 'The stolen pattern', text: 'A brocade weaver begs your help. Someone stole her new pattern, a hundred-crane design, and a rival shop is already weaving it. The rival’s doorman is a Qingcheng outer disciple.', choices: [
    R('Find proof in the rival’s workshop', 'insight', 28, O('The thread count gave him away: her loom has a fault that skips every hundredth weft. So did his cloth. The magistrate fined him and she got her cranes back.', { fame: 2, rep: { merchants: 2 } }), O('You found nothing but cats. The doorman found you.', { health: -5, rep: { orthodox: -1 } })),
    C('Tell her to weave something better', O('“Better than cranes?” she asked. “Dragons,” you said. She looked at you as if you were simple, then went home and wove dragons. They sold out in a week.', { charm: 1, sanity: 2 })),
  ] }),

  // Hangzhou
  E('gh_hangzhou_west_lake', 'jianghu', { if: { loc: 'hangzhou', age: [15, 70] }, art: 'lake', title: 'A boat on West Lake', text: 'A painted pleasure boat on West Lake. A clerk of the Golden Abacus Guild pours you tea and slides a contract across the table: a share in a salt run, no questions, profits in a year.', choices: [
    Q('Invest (40 taels)', { stat: { wealth: '>=40' } }, O('You signed. The clerk smiled the smile of a man paid by the signature.', { wealth: -40, flag: 'gh.salt_share', next: { id: 'gh_salt_return', in: 4 } })),
    R('Read the small print', 'insight', 32, O('The small print made you liable for any losses, including the boat you were sitting in. You declined, and he respected you for it, which is to say he raised his price.', { insight: 1, rep: { merchants: 2 } }), O('The small print was very small. You declined anyway, on instinct.')),
    C('Enjoy the tea and leave', O('The tea was Dragon Well, first picking. It was the only free thing on the lake.', { sanity: 3 })),
  ] }),
  E('gh_salt_return', 'jianghu', { on: 'scheduled', if: { flag: 'gh.salt_share' }, title: 'The salt run', text: 'A year later, a letter from the Golden Abacus Guild arrives about your share in the salt run.', fmt: 'letter', choices: [
    P('Open it', 0.6, O('The salt run made money. Your share came with a polite note inviting you to invest again, larger.', { wealth: 70, rep: { merchants: 3 }, unflag: 'gh.salt_share' }), O('The salt run was seized by the Court. The letter regretted to inform you, at length, that regret was all the Guild could offer.', { rep: { merchants: -2 }, sanity: -3, unflag: 'gh.salt_share' })),
  ] }),
  E('gh_hangzhou_tidal_bore', 'jianghu', { if: { loc: 'hangzhou', age: [14, 60], season: 2 }, once: false, cd: 5, danger: true, art: 'river', title: 'The Qiantang tide', text: 'Autumn, and the tidal bore comes roaring up the Qiantang like a wall of white horses. Young men ride it with flags, to prove they are not afraid. Some of them are not seen again.', choices: [
    R('Ride the tide', 'body', 38, O('You rode the white wall with a red flag in your teeth and came ashore a li upstream, half-drowned and immortal. Girls threw flowers. Boys threw up.', { fame: 4, body: 1 }), O('The tide rode you instead. You were fished out downstream by a ferryman who charged by the pound.', { health: -18, wealth: -2 })),
    C('Watch from the sea wall', O('You watched from the wall with ten thousand others. The roar went through your ribs. It made your qi feel very small and very clean.', { qi: 6, sanity: 2 })),
  ] }),

  // The Imperial Capital
  E('gh_capital_failed_scholars', 'jianghu', { if: { loc: 'capital', age: [14, 70] }, art: 'city', title: 'After the lists', text: 'The examination lists are posted. Under the wall, candidates who failed for the third or fourth time sit in silence. One is quietly writing a letter to his mother; another is quietly sharpening a knife.', choices: [
    C('Sit with the one sharpening the knife', O('You talked about nothing until the sun went down. He put the knife away. “Next time,” he said. You hoped he meant the exam.', { sanity: 2, charm: 1 })),
    Q('Buy them all a drink (8 taels)', { stat: { wealth: '>=8' } }, O('Eight failed scholars, one jug at a time. By midnight they had written a satire of the examiners that will get them all arrested someday.', { wealth: -8, fame: 1, rep: { court: -1 } })),
    R('Help one with his essay for next year', 'insight', 30, O('You worked on it together all winter. Two years later a magistrate in Hebei sent you a jar of plum wine and no explanation.', { insight: 2, rep: { court: 2 } }), O('Your advice was confident and wrong.', { insight: 1 })),
  ] }),
  E('gh_capital_knock', 'jianghu', { if: { loc: 'capital', age: [16, 80], realm: '>=1', notSect: 'easterndepot' }, once: false, cd: 6, art: 'night', title: 'A knock at night', text: 'Two men in Eastern Depot black knock at your lodging after midnight. They are very polite. They would like to know where you trained, who your master is, and why a martial artist needs to be in the capital.', choices: [
    R('Answer every question perfectly', 'insight', 28, O('Your answers were dull, consistent and true enough. They wrote everything down and left you alone. You did not sleep.', { rep: { court: 1 }, sanity: -2 }), O('You contradicted yourself about your own birthplace. They wrote that down too.', { rep: { court: -3 }, flag: 'gh.depot_file' })),
    Q('Pay them for their trouble (10 taels)', { stat: { wealth: '>=10' } }, O('They accepted the silver as if it were a confession, which in the capital it is.', { wealth: -10, flag: 'gh.depot_file' })),
    C('Leave the capital by morning', O('You were through the gate by dawn and did not stop until the walls of the Paeng fortress. Somewhere a clerk added a line beside your name: left in a hurry.', { travel: 'paeng', flag: 'gh.depot_file' })),
  ] }),

  // The frontier, the lakes, the mountains
  E('gh_jadegate_beacon', 'jianghu', { if: { loc: 'jadegate', age: [14, 80] }, art: 'desert', title: 'The last beacon', text: 'At the last beacon tower of the empire an old soldier keeps the fire ready. He has done it for forty years. The beacon has never once been lit.', choices: [
    C('Keep watch with him for a night', O('He told you about every caravan he had seen pass, and every one that had not come back. At dawn he thanked you for the company and asked you to remember his name, Bok Su-man. You will.', { sanity: 4, insight: 1 })),
    C('Ask why he stays', O('“Somebody has to be ready for the one night it matters,” he said. “Probably it will be after I am dead. That is all right.”', { sanity: 2 })),
  ] }),
  E('gh_jadegate_sandstorm', 'jianghu', { if: { loc: 'jadegate', age: [15, 60] }, once: false, cd: 5, danger: true, art: 'desert', text: 'A caravan master needs a guide to find a stranded string of camels before the sandstorm closes in. He is offering good silver and a bad map.', choices: [
    R('Go out into the sand', 'insight', 30, O('You read the dunes the way old guides do, by the wind’s grain. You brought back the camels and one very grateful boy. The caravan master paid in silver and dried apricots.', { wealth: 18, fame: 2, rep: { merchants: 2 } }), O('The storm took the map, the light and your sense of direction. You walked out on the third day, cracked and furious.', { health: -15 })),
    C('Refuse', O('You stayed behind the gate. The storm blew for three days. Nobody came back from it, and nobody blamed you.', { sanity: -2 })),
  ] }),
  E('gh_dongting_toll', 'jianghu', { if: { loc: 'dongting', age: [14, 70], notSect: 'waterfortress' }, once: false, cd: 4, danger: true, art: 'lake', title: 'The reed toll', text: 'A narrow boat slides out of the reeds. The Water Fortress collects a toll on everyone who crosses the lake: fishermen, pilgrims, ducks. The toll-taker has a ledger and a very large friend.', choices: [
    Q('Pay the toll (4 taels)', { stat: { wealth: '>=4' } }, O('You paid. He gave you a receipt, a bamboo tag stamped with a fish. It is the most official thing the Black Path has ever given you.', { wealth: -4, rep: { unorthodox: 1 } })),
    R('Argue that you are a duck', 'charm', 30, O('He laughed so hard his large friend had to hold him up. “Ducks fly free,” he said, and waved you on.', { charm: 1, rep: { unorthodox: 2 } }), O('“Ducks,” he said gravely, “pay double.”', { wealth: -6 })),
    C('Fight through', O('The large friend stood up.', { combat: { foe: { name: 'the toll-taker’s large friend', kind: 'brawler', rel: 0 }, context: 'duel', lethal: 0.1, win: { text: 'The large friend went into the lake with a splash that scared the ducks. Word will reach the Fortress.', fame: 1, rep: { unorthodox: -5 } }, lose: { text: 'You went into the lake. They fished you out and charged you the toll anyway, plus rescue.', wealth: -8 } } })),
  ] }),
  E('gh_taihang_tiger_code', 'jianghu', { on: 'road', if: { region: ['hebei', 'central'], age: [14, 70], notSect: 'greenforest' }, once: false, cd: 6, art: 'road', title: 'The Green Forest’s code', text: 'Taihang bandits block the pass, but their captain hesitates over a list nailed to a tree: the Mountain Tiger’s rules. He reads them slowly, moving his lips, looking for one that lets him rob you.', choices: [
    M('Show him your medicine pouch', 'secret.gh_tiger_code', O('“Medicine,” you said. He went pale, checked the list, and waved you through with a bow. The Mountain Tiger’s first rule: never rob a healer. His second: never let anyone see you break the first.', { sanity: 2 })),
    R('Find a rule that protects you', 'insight', 26, O('Rule eleven: no tolls from anyone travelling to a funeral. You were, you explained, going to your own, eventually. He thought about it and let you pass.', { insight: 1 }), O('Rule four: everyone pays. You paid.', { wealth: -8 })),
    Q('Pay the toll (8 taels)', { stat: { wealth: '>=8' } }, O('You paid. He wrote you a receipt, which is rule nine.', { wealth: -8 })),
  ] }),
  E('gh_willow_water_dispute', 'jianghu', { if: { loc: 'willow', age: [20, 80], happened: 'willow_raid' }, art: 'garden', title: 'The water channel', text: 'Two farmers in Willow Creek are about to kill each other over the irrigation channel. The village chief would settle it, but the chief is dead, and so is the man who dug the channel. Everyone looks at you.', choices: [
    R('Judge it fairly', 'insight', 22, O('You walked the channel, counted the fields and split the water by the hour. Both farmers felt cheated, which in a village means it was fair.', { fame: 1, sanity: 3 }), O('Your judgement pleased neither farmer, and both of them told the whole village so.', { charm: -1 })),
    C('Dig them a second channel', O('You dug for a week. Each farmer now has a channel of his own and nothing to argue about, so they argue about you.', { body: 2, health: -3, sanity: 2 })),
  ] }),

  // ── Wandering ─────────────────────────────────────────────────────
  E('gh_wander_noodle_master', 'jianghu', { on: 'wander', if: { age: [12, 80], locType: ['city', 'village'] }, once: false, cd: 8, art: 'market', title: 'The noodle seller', text: 'An old woman sells noodles from a cart at the edge of town. She pulls the dough with a flick of her wrists that makes the strands sing in the air. Three ruffians are refusing to pay her.', choices: [
    C('Step in for her', O('Before you could move, a single noodle wrapped itself around the lead ruffian’s wrist and he sat down hard. The old woman did not look up. “Sit,” she told you. “Eat.” You ate. You paid double.', { insight: 2, wealth: -2, sanity: 2 })),
    C('Watch her hands', O('You watched her hands instead of the ruffians. When they reached for her cart, she moved one shoulder, and they were on the ground. Your own wrists ached with understanding for days.', { insight: 3 })),
    C('Pay for their noodles', O('You paid for theirs. The ruffians left confused. The old woman gave you an extra egg and a look that said she had not needed you, but thank you.', { wealth: -3, charm: 1 })),
  ] }),
  E('gh_wander_challenge_letter', 'jianghu', { on: 'wander', if: { age: [16, 70], stat: { fame: '>=30' } }, once: false, cd: 5, art: 'letter', title: 'A challenge', text: 'A boy of sixteen blocks the road with a sword and a letter of challenge written in very careful characters. He has heard of you. He has decided you are his destiny.', choices: [
    C('Accept, gently', O('You crossed blades with him in a field.', { combat: { foe: { name: 'the boy with the careful letter', kind: 'brawler', rel: -1 }, context: 'spar', lethal: 0, win: { text: 'You disarmed him three times and told him what he did right each time. He bowed to the ground and went home to train for ten years.', fame: 2, sanity: 2 }, lose: { text: 'He beat you, somehow. He was so shocked he apologised. You will never hear the end of it.', fame: -2, charm: 1 } } })),
    C('Refuse and tell him to go home', O('“Come back when you are thirty,” you said. He wrote that down, carefully.', { charm: 1 })),
    R('Accept and lose on purpose', 'charm', 30, O('You lost convincingly. He went home a hero. Somewhere in his village there is a story about the day he beat you, and it is a good story.', { fame: -1, sanity: 4 }), O('He saw through it and was mortally insulted. Now he really is going to train for ten years.', { flag: 'gh.boy_rival' })),
  ] }),
  E('gh_wander_storyteller', 'jianghu', { on: ['wander', 'tavern'], if: { age: [18, 90], stat: { fame: '>=20' } }, once: false, cd: 6, art: 'inn', title: 'Your own legend', text: 'A storyteller in the market is telling the tale of {fullname}. In his version you are seven feet tall, slew a dragon, and wept only once, for a horse. Most of it is wrong.', choices: [
    C('Correct him', O('You stood up and corrected him. The crowd booed you. They preferred the dragon.', { fame: -1, charm: 1 })),
    C('Tip him and let it grow', O('You tipped him. Next year the dragon had two heads.', { wealth: -1, fame: 2 })),
    C('Ask how it ends', O('“Nobody knows yet,” he said. “That is what makes it worth telling.”', { sanity: 3 })),
  ] }),
  E('gh_wander_three_drunks', 'jianghu', { on: 'wander', if: { age: [16, 50], hasNot: 'sworn' }, once: false, cd: 6, art: 'feast', bind: { x: { age: [18, 40], realm: [0, 3], role: 'acquaintance', aff: 55 } }, title: 'Under the peach trees', text: 'Three wandering swordsmen, very drunk, are swearing brotherhood under a peach tree. They need a fourth, they explain, because three is unlucky, and you have an honest face.', choices: [
    C('Swear with them', O('You swore to live and die together. By morning two of them had forgotten your name. The third, {x}, had not. {x.He} has been writing to you ever since.', { meet: 'x', role: { x: 'friend' }, rel: { x: { aff: 15 } }, sanity: 3 })),
    C('Witness the oath instead', O('You held the incense while they swore. One cried. One fell asleep. The incense was the most sober thing there.', { charm: 1, meet: 'x' })),
    C('Leave before it gets serious', O('You left before the blood-in-wine part. Sensible. Slightly lonely.')),
  ] }),
  E('gh_wander_rain_eave', 'jianghu', { on: 'wander', if: { age: [12, 80] }, once: false, cd: 6, art: 'storm', text: 'Rain drives you under the eave of a shuttered shop. Already sheltering there: an Emei nun, a Green Forest bandit, and a cat. Nobody speaks. The cat chooses your lap.', choices: [
    C('Break the silence', O('You asked about the weather. The nun and the bandit both answered at once, glared at each other, then laughed. When the rain stopped they walked off in the same direction, still arguing.', { charm: 1, sanity: 3 })),
    C('Keep the silence', O('An hour of rain and three people pretending not to be dangerous. When it stopped, the bandit tipped his hat to the nun, and the nun almost smiled.', { insight: 1, sanity: 2 })),
    C('Keep the cat', O('The cat followed you for three towns and then left you for a fishmonger. Cats are the true wanderers of the Gangho.', { sanity: 4 })),
  ] }),
  E('gh_wander_bounty_board', 'jianghu', { on: 'wander', if: { age: [16, 60], locType: 'city', realm: '>=1' }, once: false, cd: 5, danger: true, art: 'city', title: 'The bounty board', text: 'On the magistrate’s wall: a bounty of forty taels for “One-Ear Chae,” wanted for six robberies and a murder. Below it someone has scrawled: “He drinks at the dyers’ well at dusk.”', choices: [
    C('Go to the dyers’ well at dusk', O('He was there, and he had friends.', { combat: { foe: { name: 'One-Ear Chae', kind: 'bandit', rel: 0 }, context: 'ambush', lethal: 0.3, win: { text: 'You dragged One-Ear Chae to the magistrate in the morning. The magistrate paid, eventually, after a fee for paying.', wealth: 35, fame: 3 }, lose: { text: 'Chae left you in the dyers’ vat. You were blue for a week, which was worse than the bruises.', fame: -2, charm: -1 } } })),
    R('Find out who wrote the note', 'insight', 28, O('A dyer’s widow. Chae killed her husband. She did not want the money; she wanted someone to listen. You listened, then told the magistrate exactly where to send his men.', { fame: 1, sanity: 2, rep: { court: 2 } }), O('Nobody would talk to you. Dyers are close-mouthed people with blue hands.')),
    C('Leave it for someone else', O('Someone else took it. You heard later that it went badly for them.')),
  ] }),
  E('gh_wander_chivalry_debt', 'jianghu', { on: 'wander', if: { age: [20, 70], stat: { fame: '>=15' } }, once: true, art: 'road', title: 'The cost of a good deed', text: 'A man in mourning white stops you on the road. Years ago, he says, you drove off bandits from a farm. One of them was his brother. His brother’s children have been starving ever since. He is not here to fight. He just wanted you to know.', choices: [
    Q('Give him money for the children (20 taels)', { stat: { wealth: '>=20' } }, O('He took it without thanks. You did not expect any. Chivalry is a coin with a face on each side.', { wealth: -20, sanity: 2, fame: 1 })),
    C('Tell him you would do it again', O('“I know,” he said. “So would I, in your place. That is what makes it hard.” He walked away. You thought about it for a long time.', { sanity: -4, insight: 2 })),
    C('Ask the children’s names', O('He told you. You wrote them down. You do not know yet what you will do with them, but you have them.', { sanity: -1, flag: 'gh.bandit_orphans' })),
  ] }),
  E('gh_wander_disciple_beggar', 'jianghu', { on: 'wander', if: { age: [30, 90], realm: '>=2', hasNot: 'disciple' }, art: 'road', bind: { x: { age: [9, 12], realm: 0, role: 'acquaintance', aff: 50, romance: false } }, title: 'The child who follows', text: 'A skinny child has followed you for three days, copying your walk and your stance from a careful distance. When you finally turn around, {x.he} drops to {x.his} knees. “Teach me,” {x.he} says. “I can sweep. I can carry things. I eat almost nothing.”', choices: [
    C('Take {x.him} as your disciple', O('You took {x.him}. {x.He} eats a great deal, as it turns out, and sweeps very badly. {x.He} is also the best thing that has happened to you in years.', { meet: 'x', role: { x: 'disciple' }, rel: { x: { aff: 20, res: 20 } }, achieve: 'first_disciple', sanity: 5 })),
    C('Find {x.him} a sect instead', O('You walked {x.him} to the nearest sect gate and vouched for {x.him}. {x.He} cried, and waved, and went in. A sect is a better teacher than a wanderer. You tell yourself that.', { meet: 'x', fame: 1, rep: { orthodox: 1 } })),
    C('Send {x.him} home', O('“I don’t have a home,” {x.he} said, and walked away before you could answer.', { sanity: -4 })),
  ] }),
  E('gh_wander_sword_tomb', 'jianghu', { on: 'wander', if: { age: [16, 90], region: ['guanzhong', 'shu', 'jingchu'] }, once: false, cd: 10, art: 'grave', title: 'A swordsman’s grave', text: 'On a hilltop, a mound of stones with a rusted sword driven into it. A wooden board says only: “He was faster than everyone but one.”', choices: [
    C('Pour out some wine for him', O('You poured wine on the stones and told him about your day. It seemed polite. The wind made the sword hum, which may have been a reply.', { sanity: 3 })),
    R('Study the sword’s angle', 'insight', 34, O('Whoever drove it into the stones did so with a twist at the end, a flourish only a master would bother with. You copied the twist in practice for a month, and something in your swordwork tightened.', { insight: 2, qi: 6 }), O('It is a rusty sword in some rocks.')),
    C('Take the sword', O('It would not come out. You pulled until your hands bled. You left, feeling watched, and mildly ashamed.', { health: -2, sanity: -2 })),
  ] }),

  // ── On the road ──────────────────────────────────────────────────
  E('gh_road_funeral', 'jianghu', { on: 'road', if: { age: [12, 90] }, once: false, cd: 6, art: 'grave', text: 'A funeral procession fills the road: white banners, paper horses, a coffin carried by men who walk like martial artists. A sect elder is going home for the last time.', choices: [
    C('Step aside and bow', O('You stepped aside and bowed. A young disciple at the back bowed back to you, red-eyed, grateful that a stranger noticed.', { rep: { orthodox: 1 }, sanity: 1 })),
    C('Walk with them to the next town', O('You walked with them. At the inn that night they told you about the elder: his temper, his terrible jokes, the way he paid for every disciple’s medicine himself. You drank to a man you never met.', { sanity: 3, rep: { orthodox: 2 } })),
    C('Overtake them', O('You pushed past. The disciples looked at you the way you would look at someone who pushed past your master’s coffin.', { rep: { orthodox: -2 } })),
  ] }),
  E('gh_road_rival_escorts', 'jianghu', { on: 'road', if: { age: [14, 70] }, once: false, cd: 6, danger: true, art: 'road', title: 'Two flags', text: 'Two escort agencies meet at a narrow pass, each with a cart, each with a flag, neither willing to back down. Their chiefs have been staring at each other since noon.', choices: [
    R('Propose they share the pass in turns', 'charm', 24, O('You proposed the older agency go first and the younger agency get the better inn. Both chiefs pretended this had been their idea. You ate dinner on both of them.', { charm: 1, rep: { merchants: 2 } }), O('Both chiefs told you to mind your own business, for once in agreement.')),
    C('Wait it out', O('You sat on a rock and ate a pear. At dusk they both reversed at once and jammed the pass completely. You took the goat track.', { sanity: 1 })),
    C('Offer to fight for whichever pays more', O('The younger agency paid. The older agency sent their best spearman.', { combat: { foe: { name: 'the old agency’s spearman', kind: 'soldier', rel: 0 }, context: 'duel', lethal: 0.08, win: { text: 'You won the pass for the younger agency. The older chief never forgot your face.', wealth: 10, rep: { merchants: 1 } }, lose: { text: 'You lost the pass and the fee. The younger chief never forgot your face either.', rep: { merchants: -2 } } } })),
  ] }),
  E('gh_road_snow_pass', 'jianghu', { on: 'road', if: { age: [12, 90], season: 3 }, once: false, cd: 4, danger: true, art: 'snow', text: 'Snow closes the pass behind you and ahead of you. There is a shepherd’s hut, already holding a family of five and a goat, and room, just, for one more.', choices: [
    C('Squeeze in', O('Five people, a goat and you, for four days. The children taught you a counting song. The goat ate your hat. You all lived.', { sanity: 4 })),
    R('Push through the snow', 'body', 32, O('You pushed through to the far side in a day and a night, cursing every step. Frost-bitten, but through.', { body: 1, health: -6 }), O('You turned back half-frozen. The family made room again without a word.', { health: -14 })),
    C('Give them your food and sleep outside the door', O('You slept in the lee of the hut wrapped in your own qi. In the morning the grandmother made you tea with your own leaves and scolded you for being a fool.', { health: -6, sanity: 3, fame: 1 })),
  ] }),
  E('gh_road_wounded_assassin', 'jianghu', { on: 'road', if: { age: [15, 80] }, once: true, art: 'night', title: 'A blade in the ditch', text: 'A woman in black lies in the ditch with a crossbow bolt in her thigh. Blood Shadow Pavilion, by the knot on her sleeve. She watches you with flat, professional eyes. “If you help me,” she says, “you will be sorry. If you don’t, so will I.”', choices: [
    C('Pull the bolt and bind it', O('You bound it. She was gone before dawn, along with your spare shirt. In its place: a black paper token with a red thumbprint. You suspect it is worth one life, and not necessarily yours.', { flag: 'gh.shadow_token', rep: { unorthodox: 3 }, codex: { id: 'secret.gh_shadow_token', cat: 'secrets', title: 'A Blood Shadow token', text: 'A wounded Blood Shadow assassin left you a black paper token with a red thumbprint. The Pavilion honours them: one contract refused, or one contract given.' } })),
    C('Call the constables', O('The constables came. She was not in the ditch when they arrived, only the bolt, cleaned and laid neatly on a stone, pointing at you.', { rep: { court: 2, unorthodox: -4 }, sanity: -2 })),
    C('Walk on', O('You walked on. Behind you, very softly, she laughed.')),
  ] }),
  E('gh_road_begging_monk', 'jianghu', { on: 'road', if: { age: [12, 80] }, once: false, cd: 8, art: 'temple', text: 'A huge monk sits in the middle of the road with an empty bowl. He does not ask for anything. He also does not move. Carts are backing up behind you.', choices: [
    Q('Put a meal’s worth in his bowl (1 tael)', { stat: { wealth: '>=1' } }, O('He stood, bowed, and stepped aside. As you passed he said, without looking up, “Your left foot is lazy.” It is. You have been fixing it ever since.', { wealth: -1, body: 1, insight: 1 })),
    R('Try to move him', 'power', 40, O('You leaned into him with all your qi. He rocked back a finger’s width, smiled hugely and stood up. “Good,” he said. “Shaolin will be pleased to hear the roads are safe.”', { rep: { orthodox: 3 }, fame: 1 }), O('You leaned into him with all your qi. It was like leaning on Mount Song. He laughed until the carts behind you started laughing too.', { charm: -1, body: 1 })),
    C('Sit down next to him', O('You sat next to him. After an hour he said, “Well, now we are two,” and got up and left. You still do not know what that was about.', { sanity: 3, insight: 1 })),
  ] }),

  // ── Arriving ─────────────────────────────────────────────────────
  E('gh_arrive_rain_inns', 'jianghu', { on: 'arrive', if: { locType: 'city', age: [12, 80] }, once: false, cd: 4, art: 'inn', text: 'You arrive in {loc} in pouring rain. Every inn is full. A Beggars’ Sect boy with a pouch on his belt offers you a dry spot under a bridge for a copper, “with conversation.”', choices: [
    C('Take the bridge', O('Dry, mostly. The conversation was excellent: three beggars, all the news of {loc}, and a very good story about a magistrate’s wig.', { wealth: -1, insight: 1, rep: { orthodox: 1 } })),
    Q('Bribe an innkeeper for a room (6 taels)', { stat: { wealth: '>=6' } }, O('The innkeeper found a room that had been full a moment ago. Its previous occupant slept in the stable, glaring.', { wealth: -6, health: 3 })),
    C('Walk the rain all night', O('You walked {loc} all night in the rain and learned its streets better than most people who live there.', { health: -4, insight: 1 })),
  ] }),
  E('gh_arrive_gate_tax', 'jianghu', { on: 'arrive', if: { locType: ['city', 'frontier'], age: [14, 80], stat: { wealth: '>=20' } }, once: false, cd: 5, art: 'city', text: 'The gate clerk at {loc} declares a new tax on “travellers carrying more than twenty taels.” He invented it, as far as you can tell, a moment ago.', choices: [
    C('Pay it', O('You paid two taels to a man who wrote it down in a book that does not exist.', { wealth: -2 })),
    R('Quote him the actual regulation', 'insight', 26, O('You quoted the regulation, article and clause. He went pale and waved you through. You made the article up too.', { insight: 1 }), O('He quoted a different regulation. His was also made up, but he had a stamp.', { wealth: -4 })),
    C('Report him to the magistrate', O('The magistrate thanked you, fined the clerk and pocketed the fine. The system works.', { rep: { court: 1 } })),
  ] }),
  E('gh_arrive_home_again', 'jianghu', { on: 'arrive', if: { home: true, age: [18, 90], has: 'parent' }, bind: { x: 'parent' }, once: false, cd: 6, art: 'garden', title: 'Home', text: 'The road brings you back to {home}. Everything is smaller than you remember. {x} is at the gate before you reach it, as if {x.he} had been waiting there for years, which perhaps {x.he} had.', choices: [
    C('Stay a while', O('You stayed for a season: mended a roof, ate too much and listened to the same stories you could recite by heart. When you left, the bundle of food was too heavy to carry and you carried it anyway.', { sanity: 8, health: 4, rel: { x: { aff: 10 } } })),
    C('Tell them about the Gangho', O('You told them everything, leaving out the parts that would make them worry, which was most of it. They listened as if you were the storyteller in the market.', { sanity: 4, rel: { x: { aff: 5, res: 5 } } })),
  ] }),

  // ── Tavern talk and rankings ──────────────────────────────────────
  E('gh_tavern_ten_heavens', 'jianghu', { on: 'tavern', if: { age: [12, 90] }, once: false, cd: 5, art: 'inn', title: 'Who is strongest', text: 'The whole tavern is arguing about who is strongest under Heaven. One table says the Pure Cloud Daoist of Wudang. One says the Drunken Sword Saint. A third insists it is “a cook in Mount Hua,” and will not explain.', choices: [
    C('Take a side', O('You said the Sword Saint. Half the tavern bought you drinks. The other half threw buns. It was a good evening.', { charm: 1, health: -1 })),
    C('Ask about the cook', O('“Granny Pyo,” the man said. “Nobody alive has ever eaten a bad meal from her, and nobody alive has ever won an argument with her. Strongest under Heaven.” You could not argue.', { insight: 1, codex: 'people.hua_cook' })),
    R('Name someone nobody has heard of', 'fame', 40, O('You named yourself. The tavern went quiet. Then someone at the back said, “Actually…” and told a story about you. You left before it got worse.', { fame: 2 }), O('You named yourself. The tavern laughed for a full minute. You left before it got worse.', { charm: -1 })),
  ] }),
  E('gh_tavern_poison_cup', 'jianghu', { on: 'tavern', if: { age: [16, 80], stat: { infamy: '>=10' } }, once: false, cd: 6, danger: true, art: 'inn', text: 'Your wine smells faintly of bitter almond. Across the room, a man you do not know very carefully does not look at you.', choices: [
    R('Swap cups with your neighbour', 'body', 30, O('Quick hands. Your neighbour drank yours, made a face, and was sick for a day; whoever poisoned it had been stingy. The man in the corner was gone.', { infamy: 1, sanity: -2 }), O('Your neighbour caught you swapping and threw the cup in your face. Some went in your mouth.', { health: -15 })),
    C('Leave the wine and follow him', O('He ran. You let him. But now you know his face, and he knows you know it.', { insight: 1, flag: 'gh.poisoner_face' })),
    Q('Drink it, and channel the poison out', { realm: '>=3' }, O('You drank, toasted him, and sweated the poison out of your fingertips onto the table, where it smoked. He fled through the window. The innkeeper charged you for the table.', { fame: 3, wealth: -2 })),
  ] }),
];

// ── Hand-written: history's edges ─────────────────────────────────────
const HISTORY = [
  // Years 2–16
  L('gh_comet_blame', 'timeline', { happened: 'comet', year: [3, 6], age: [2, 5] }, 'Your grandmother tells everyone that the comet in your second year is the reason you bite. You bite her, to prove her right.', { charm: -1, sanity: 1 }),
  E('gh_mourning_white', 'timeline', { if: { happened: 'emperor_dies', year: [5, 7], age: [4, 6] }, art: 'palace', title: 'The year of white', text: 'The old Emperor is dead. For a hundred days nobody may wear colour, play music or marry. The grown-ups whisper about a boy on the throne and men in black behind him.', choices: [
    C('Hum anyway', O('You hummed a planting song under your breath. Your mother clapped a hand over your mouth, then, when nobody was looking, hummed the second verse with you.', { sanity: 2, charm: 1 })),
    C('Ask who the men in black are', O('“The Eastern Depot,” your father said, and then, very firmly, “We never say their name in the street.” You remembered the name, and the firmness.', { insight: 1, codex: 'timeline.emperor_dies' })),
  ] }),
  E('gh_boy_emperor_kite', 'timeline', { if: { happened: 'emperor_dies', loc: 'capital', year: [9, 16], age: [9, 15] }, art: 'palace', title: 'A kite over the red wall', text: 'A yellow kite with a dragon on it drifts over the palace wall and tangles in a willow above your head. On the other side of the wall, a boy’s voice shouts, then goes quiet, as if someone has told it to.', choices: [
    C('Climb the willow and send it back', O('You freed the kite and let it go on the wind. It rose, wobbled, and was reeled back over the wall. A moment later a small hand waved above the tiles. You waved back at the Emperor of the world.', { sanity: 4, rep: { court: 1 } })),
    C('Keep it', O('You kept it under your bed for years. Nobody came looking. Somehow that was the saddest part.', { sanity: -1, insight: 1 })),
    R('Write a message on it first', 'insight', 20, O('“Do you have any friends?” you wrote, and sent it back. The next morning a second kite came over the wall. On it, in careful brush: “One. Now.”', { sanity: 5, flag: 'gh.kite_friend' }), O('You wrote a message. A Depot officer on the wall read it before the boy did, and looked at you for a long time.', { rep: { court: -2 }, flag: 'gh.depot_file' })),
  ] }),
  E('gh_hua_notice', 'timeline', { if: { region: 'guanzhong', year: [9, 11], age: [8, 10], sect: 'none', timeline: { hua_exam: 'pending' } }, art: 'mountain', title: 'A notice on the wall', text: 'A notice is pasted on the wall by the well: the Mount Hua Sect will hold its entrance examination in the spring of the eleventh year. Children of good health and good character may present themselves. Somebody has added, in charcoal, “and good luck.”', choices: [
    R('Beg to be taken to sit it', 'body', 16, O('Your family argued for a week, then packed you rice cakes. You climbed Mount Hua with ninety other children. You were one of the eleven they kept.', { join: 'mounthua', travel: 'mounthua', codex: 'timeline.hua_exam' }), O('You climbed Mount Hua with ninety other children and came down with eighty. The examiner said, “Next time,” kindly, which was the worst part.', { body: 1, codex: 'timeline.hua_exam' })),
    M('You remember what the examiner is really testing', 'timeline.hua_exam', O('Everyone else raced to the top. You stopped to help a boy who had fallen, as the examiner had hoped someone would. He wrote your name first. The boy you helped was Yu Jin, a year early and very grateful.', { join: 'mounthua', travel: 'mounthua', meet: '@yujin', rel: { '@yujin': { aff: 20 } } })),
    C('Stay home', O('You stayed home. The notice faded in the rain. You did not think about it often, except every time you looked at the mountain.')),
  ] }),
  E('gh_fleet_gathers', 'timeline', { if: { loc: 'wuchang', year: [11, 13], age: [12, 80], timeline: { grain_fleet: 'pending' } }, art: 'ship', title: 'The grain fleet gathers', text: 'Forty imperial grain barges crowd the Wuchang harbour, bound downriver with the tax rice of three provinces. A boatman you drink with keeps counting them, and writing something on his sleeve.', choices: [
    R('Report the boatman to the fleet officer', 'charm', 32, O('The officer did not believe you until they searched the boatman and found a Water Fortress tag sewn into his collar. The fleet changed its route and its sailing day. In the thirteenth year, it arrived.', { avert: 'grain_fleet', flag: 'gh.fleet_warned', rep: { court: 6, unorthodox: -6 }, fame: 4, gaze: 1 }), O('The officer had you thrown off the quay for slandering an honest boatman. The boatman bought you a drink afterwards, smiling.', { rep: { court: -1 } })),
    M('Tell the officer where the fleet will be sunk', 'timeline.grain_fleet', O('You described the narrows, the chains, the fire-rafts, all of it. The officer went white, because it was exactly what he would have done. He changed everything. The Water Fortress waited at the narrows for a fleet that never came.', { avert: 'grain_fleet', flag: 'gh.fleet_warned', rep: { court: 8, unorthodox: -8 }, fame: 5, gaze: 1 })),
    C('Sell what you saw to the Water Fortress', O('The boatman’s friends paid you well for nothing they did not already know. It felt like money for silence, which it was.', { wealth: 25, infamy: 2, rep: { unorthodox: 5 } })),
    C('Mind your own business', O('You drank your wine. The boatman finished counting.', { codex: 'timeline.grain_fleet' })),
  ] }),

  // Years 19–29
  E('gh_vote_bought', 'timeline', { if: { loc: 'luoyang', year: [19, 22], age: [15, 90], timeline: { alliance_vote: 'pending' } }, art: 'night', title: 'A unanimous vote', text: 'In the lane behind the Alliance hall, after dark, the Alliance Leader’s steward hands a heavy purse to a delegate of the Qingcheng Sect. The delegate bows, very low, to a purse.', choices: [
    C('Remember their faces', O('You remembered their faces, the purse, the date. In the twenty-second year, Hwangbo Jun was re-elected unanimously. You were one of the few who knew how unanimous it was.', { codex: { id: 'secret.gh_bought_vote', cat: 'secrets', title: 'A bought vote', text: 'In year 21, Hwangbo Jun’s steward paid the Qingcheng delegate behind the Alliance hall. Every sect’s vote in year 22 was bought the same way; only Mount Hua’s was not, because Mount Hua could not be bothered to sell it.' } })),
    C('Tell the Beggars’ Sect', O('Hong Chil, chief of the Beggars’ Sect, listened, picking his teeth with a chicken bone. “I know,” he said. “Everybody knows. That is the trouble with the Alliance. Still, it is nice to be told.” He tossed you the bone, which in the Beggars’ Sect is high praise.', { meet: '@beggar_chief', rel: { '@beggar_chief': { res: 10 } }, rep: { orthodox: 2 }, codex: 'timeline.alliance_vote' })),
    R('Blackmail the delegate', 'charm', 30, O('The delegate paid you twice what the steward paid him. You have never felt more like a member of the Murim Alliance.', { wealth: 40, infamy: 3, rep: { orthodox: -4 } }), O('The delegate called you a liar loudly, in front of witnesses. The Alliance believed him; it had to.', { rep: { orthodox: -6 }, infamy: 1 })),
  ] }),
  E('gh_envoy_road', 'timeline', { if: { region: 'hebei', year: [23, 25], age: [14, 90], timeline: { beggar_envoy: 'pending' } }, art: 'road', title: 'A beggar with a message', text: 'A ragged man with nine knots in his belt falls into step with you on the capital road. A Beggars’ Sect envoy, carrying something sewn into his sleeve. Two riders in grey have been keeping exactly his pace for a day.', choices: [
    R('Lose the riders in the market crowds', 'insight', 30, O('You walked him through three markets, a funeral and a bathhouse. The riders lost you at the bathhouse. In the safe room he unpicked his sleeve and told you what he carried: a Mount Hua elder’s debts, bought by the Cult. Then he went home by another road, alive.', { avert: 'beggar_envoy', codex: 'secret.gu_debts', rep: { orthodox: 6 }, gaze: 1, flag: 'gh.envoy_saved' }), O('The riders did not lose you. They took him at the next gate, politely, and told you to have a pleasant day.', { sanity: -5, rep: { court: -1 } })),
    M('You know they take him at the Xuanwu gate', 'timeline.beggar_envoy', O('You steered him around the Xuanwu gate and in through a night-soil cart at the south wall. He smelled terrible and lived. Sewn in his sleeve: proof that the Cult owns a Mount Hua elder’s debts.', { avert: 'beggar_envoy', codex: 'secret.gu_debts', rep: { orthodox: 8 }, gaze: 1, flag: 'gh.envoy_saved' })),
    C('Keep your distance', O('You let him walk ahead. At the gate the grey riders closed around him like water. He did not look back at you. You were grateful, and ashamed of being grateful.', { sanity: -3, codex: 'timeline.beggar_envoy' })),
  ] }),
  E('gh_saint_reed_hut', 'timeline', { if: { loc: 'dongting', year: [20, 29], age: [14, 90], alive: 'sword_saint', notMet: 'sword_saint' }, art: 'lake', title: 'A reed hut on the east shore', text: 'Fishermen talk about a drunk who lives in the reeds on the east shore of Lake Dongting and shouts at the moon. Some nights, they say, the moon’s reflection comes apart in two clean halves.', choices: [
    R('Search the east shore', 'insight', 30, O('You found the hut on the fourth night by the smell of wine. An old man sat outside it with a sword across his knees, staring at the water. “Sit,” said Dokgo Ung, the Drunken Sword Saint, “and be quiet. The moon is nearly here.”', { meet: '@sword_saint', insight: 2, codex: 'timeline.saint_dongting' }), O('You found nine reed huts. None of them had a sword saint in them. One had a very angry heron.')),
    M('Go straight to the hut', 'timeline.saint_dongting', O('You walked straight to the hut, a jar of wine in each hand. Dokgo Ung looked at you, at the wine, and back at you. “Somebody told you,” he said. “Somebody who is dead now, I expect. Well. Sit.”', { meet: '@sword_saint', rel: { '@sword_saint': { aff: 15, res: 10 } }, insight: 2 })),
    Q('Leave a jar of wine at the water’s edge', { item: 'rice_wine' }, O('In the morning the jar was empty and set upright on a stone, and someone had scratched a single sword stroke beside it so clean that you studied it for a month.', { take: { rice_wine: 1 }, insight: 3, qi: 6 })),
  ] }),
  E('gh_poison_caravan', 'timeline', { if: { loc: 'jadegate', year: [25, 28], age: [15, 90], timeline: { demon_poisoned: 'pending' } }, art: 'desert', title: 'Medicine for the west', text: 'A small caravan clears the Jade Gate with Dang family seals on its boxes and Cult passes in its drivers’ belts. “Medicine,” says the lead driver, too quickly. The boxes are sealed with black wax, the colour the Dang use for things that are not medicine.', choices: [
    R('Get a look inside a box', 'insight', 35, O('Glass phials packed in rice husk, each with a red thread: Seven-Night Lotus, a Dang poison that kills an old man in his sleep and looks like age. Somebody in the Ten Thousand Mountains is planning a funeral.', { codex: { id: 'secret.gh_poison_road', cat: 'secrets', title: 'Seven-Night Lotus', text: 'In years 25–28 the Blood Faction buys Seven-Night Lotus from a Dang supplier and carries it west through the Jade Gate. It kills an old man in his sleep and looks like age. That is how the old Heavenly Demon dies.' } }), O('The driver caught you at the boxes and broke your fingers for your curiosity, very professionally.', { health: -12, injury: { name: 'broken fingers', seasons: 3, sev: 5 } })),
    M('Switch the phials for river water', 'secret.gh_poison_road', O('You knew the red thread and the black wax. One night at the caravanserai you switched every phial for river water and watched the caravan go west in the morning, carrying nothing. In the Ten Thousand Mountains, an old man would wake up.', { avert: 'demon_poisoned', gaze: 2, rep: { cult: 3 }, fame: 2 })),
    C('Let them pass', O('They passed. That winter, news came from the west: the old Heavenly Demon had died in his sleep, of age.', { codex: 'timeline.demon_poisoned' })),
  ] }),

  // Years 31–34: the shepherd, the border, the red cloth
  E('gh_shepherd', 'timeline', { if: { region: 'guanzhong', happened: 'traitor_meeting', year: [31, 32], age: [14, 90], not: 'traitor.exposed', alive: 'hua_traitor' }, art: 'mountain', title: 'Nobody believed him', text: 'An old shepherd in a wine-shop tells anyone who will listen: he saw a Mount Hua elder at the western border meeting riders in masks. The riders come back, he says, every new moon. The wine-shop laughs at him. He has stopped expecting anything else.', choices: [
    C('Believe him, and go see', O('You bought him a jug and got directions to the place. The next new moon is two seasons away.', { flag: 'gh.shepherd', next: { id: 'gh_border_watch', in: 2 } })),
    M('Ask him whether the elder was smiling', 'timeline.traitor_meeting', O('“Smiling,” he said, startled. “The whole time. Who smiles at men in masks?” You knew exactly who.', { flag: 'gh.shepherd', next: { id: 'gh_border_watch', in: 1 }, sanity: -2 })),
    C('Laugh with the others', O('You laughed with the others. The shepherd finished his wine and went back to his sheep. Years later you remembered his face very clearly.', { codex: 'timeline.traitor_meeting' })),
  ] }),
  E('gh_border_watch', 'timeline', { on: 'scheduled', if: { not: 'traitor.exposed' }, art: 'night', title: 'The new moon', text: 'The new moon. You lie in the frozen grass on the western border where the shepherd said. Near midnight, horses: four riders in masks, and a fifth man on foot in Mount Hua grey, who walks out to meet them as if greeting old friends.', choices: [
    R('Get close enough to hear', 'insight', 30, O('Close enough to hear the price: a map of the Plum Blossom Path, for a debt forgiven and a sack of silver. Close enough to see the man’s face when he laughed. Elder Gu Dal-pyeong.', { flag: 'gh.saw_gu', codex: { id: 'secret.gh_border_meeting', cat: 'secrets', title: 'The new-moon meeting', text: 'From year 31, on every new moon, Elder Gu Dal-pyeong of Mount Hua meets Cult riders on the western border and sells them the Plum Blossom Path, piece by piece. A shepherd saw it first; nobody believed him.' } }), O('A horse caught your scent and screamed. You ran, with arrows hissing through the grass behind you, and saw nothing but the backs of your own hands.', { health: -10 })),
    R('Follow the riders afterwards', 'body', 34, O('You trailed them west to the old salt mines, where red banners hung in the dark. A Cult camp, a day’s ride from Mount Hua, that the Alliance swears does not exist.', { codex: 'secret.cult_signals', rep: { cult: -2 }, insight: 1 }), O('You lost them in the hills by dawn, and nearly lost yourself.', { health: -6 })),
    C('Leave before you are seen', O('You saw enough: a man in Mount Hua grey, laughing with masked men. You did not see his face. Some nights, you are glad.', { sanity: -3 })),
  ] }),
  E('gh_border_accuse', 'timeline', { if: { loc: 'mounthua', year: [31, 33], mem: 'secret.gh_border_meeting', not: 'traitor.exposed', alive: 'hua_traitor' }, art: 'temple', title: 'What you saw at the border', text: 'You know what you saw on the new moon: Elder Gu Dal-pyeong, the masked riders, the price of the Plum Blossom Path. Elder Gu is in the courtyard now, smiling at the juniors, handing out sweets.', choices: [
    R('Bring the shepherd before the Sect Leader', 'fame', 34, O('You carried the old shepherd up the mountain on your back. He told it again, the way he had told it in the wine-shop, and this time Sect Leader Hyeon Mu-gyeong listened. On the next new moon, Mount Hua’s elders lay in the frozen grass themselves. Gu Dal-pyeong came out smiling.', { flag: 'traitor.exposed', rep: { orthodox: 10 }, fame: 8, gaze: 1, meet: '@hua_leader' }), O('Sect Leader Hyeon Mu-gyeong heard you out, and the shepherd, and then Gu Dal-pyeong, who laughed and wept and called it slander from a drunk. The Sect Leader believed his elder. Of course he did.', { rep: { orthodox: -5 }, sanity: -6 })),
    R('Watch the path yourself on the next new moon, with witnesses', 'charm', 30, O('You talked two Mount Hua disciples into lying in the grass with you. When Gu Dal-pyeong walked out to greet the riders, they saw his face. The sect could not ignore its own.', { flag: 'traitor.exposed', rep: { orthodox: 8 }, fame: 5, gaze: 1 }), O('Nobody would come. Even the juniors like Elder Gu. He gives out sweets.')),
    C('Wait for proof that cannot be argued with', O('You waited. History, it turns out, does not.', { sanity: -2 })),
  ] }),
  E('gh_red_cloth', 'timeline', { if: { region: 'guanzhong', year: [32, 34], age: [14, 90], flag: 'w.war_coming' }, art: 'forest', title: 'Red cloth on dead trees', text: 'All along the western hills, strips of red cloth are tied to dead trees, a few li apart, in a line that points toward Mount Hua. The local constable says children did it.', choices: [
    M('Read the cloth', 'secret.cult_signals', O('You knew the signals: one knot for water, two for a camp, three for a path. The three-knot line ran straight to the Plum Blossom cliffs. You cut down every strip and wrote it all down for anyone who would listen.', { codex: { id: 'secret.gh_scout_line', cat: 'secrets', title: 'The three-knot line', text: 'In years 32–33, Cult scouts mark a line of three-knot red cloth from the western salt mines to the cliffs below Mount Hua’s Plum Blossom Path. Cutting it slows them; it does not stop them.' }, rep: { orthodox: 3, cult: -3 }, merit: 5 })),
    R('Report it to the Alliance', 'fame', 40, O('The Alliance sent an inspector. He looked at the cloth, wrote a report and went home. The report said “children.” But Mount Hua heard, and doubled the night watch for a month.', { rep: { orthodox: 3 }, fame: 2, codex: 'timeline.cult_scouts' }), O('The Alliance thanked you for your vigilance and asked you to stop wasting its paper.', { codex: 'timeline.cult_scouts' })),
    C('Cut one down and keep it', O('You kept a strip of red cloth in your sleeve. You are not sure why. Some warnings are for carrying.', { insight: 1 })),
  ] }),
  E('gh_peace_envoy', 'timeline', { if: { happened: 'peace_kept', loc: 'luoyang', year: [35, 45], alive: 'haryeong', age: [16, 90] }, art: 'palace', title: 'An envoy in red', text: 'For the first time in two hundred years, an envoy of the Heavenly Demon Divine Cult walks openly through Luoyang to the Alliance hall. She is young, unarmed and smiling at the people who are spitting at her. Her name is Dan Ha-ryeong.', choices: [
    C('Walk beside her', O('You fell in beside her without a word. She glanced at you. “Brave,” she said, “or stupid?” “Yes,” you said. She laughed out loud in the middle of Luoyang, and some of the spitting stopped.', { meet: '@haryeong', rel: { '@haryeong': { aff: 15, res: 10 } }, rep: { cult: 6, orthodox: -3 }, fame: 2 })),
    C('Watch from the crowd', O('You watched her climb the Alliance steps and bow to men who would have killed her ten years ago in another world. In this one, they bowed back, stiffly.', { sanity: 3, insight: 1 })),
    R('Stop a man drawing a knife', 'body', 30, O('You caught his wrist in the crowd and pressed until the knife fell. Nobody saw but her. She inclined her head to you a finger’s width, like a queen.', { meet: '@haryeong', rel: { '@haryeong': { res: 20 } }, rep: { cult: 8 } }), O('You missed his wrist; her guards did not. The man was carried off. She looked at you as if wondering which side you had been on.', { meet: '@haryeong' })),
  ] }),

  // Years 16, 26, 36: the Snow Lotus
  E('gh_lotus_climb', 'timeline', { if: { loc: 'kunlun', season: 1, age: [14, 120], or: [{ year: [16, 16] }, { year: [26, 26] }, { year: [36, 36] }] }, once: false, cd: 9, danger: true, art: 'snow', title: 'The north face', text: 'The Snow Lotus has bloomed somewhere on Kunlun’s glaciers, and the whole mountain is crawling with pilgrims, thieves and Kunlun disciples chasing both away. Somewhere up there is a flower worth more than a manor.', choices: [
    R('Climb and search', 'body', 42, O('Three days on the ice. On the third, in a crack where the wind could not reach, a white flower with a heart like frost. Your hands shook taking it.', { item: { snow_lotus: 1 }, health: -10, fame: 1 }), O('The ice won. A Kunlun disciple found you in a crevasse and hauled you out on a rope, lecturing the whole way.', { health: -20, rep: { orthodox: -2 } })),
    M('Climb the north face, where it always blooms', 'timeline.snow_lotus_16', O('Everyone else searched the south slopes. You went straight to the north face, where the wind is worst and nobody looks, and found it in the same crack as always, waiting for you like an old friend.', { item: { snow_lotus: 1 }, health: -6 })),
    C('Sell rope to the pilgrims instead', O('You sold rope, tea and directions at the foot of the glacier. More money than any flower, and less frostbite.', { wealth: 15, rep: { merchants: 1 } })),
  ] }),

  // Years 55–60: the Registry, the Beggars, the coup
  E('gh_registry_desk', 'timeline', { if: { happened: 'registry_edict', locType: 'city', year: [55, 60], age: [16, 120], realm: '>=1', not: 'gh.registry' }, art: 'palace', title: 'The Registry desk', text: 'In the square, a Depot clerk sits behind a desk with a brush, an ink-stone and a list. Every martial artist in the city must give a name, a sect, a master and a thumbprint. The queue is long and very quiet.', choices: [
    C('Register', O('You gave your name and your thumbprint. The clerk wrote it in a book that will outlive you. You feel watched now, always, which is the point.', { flag: 'gh.registry', rep: { court: 5, orthodox: -3 }, sanity: -3 })),
    R('Register under a false name', 'insight', 34, O('“Bak Mu-myeong,” you said, Nobody-in-Particular, from a village that burned down. The clerk wrote it without blinking. Somewhere, you are now two people.', { flag: 'gh.registry', insight: 1 }), O('The clerk looked up. “Your accent is from {region},” he said, “and that village is not.” You walked away fast.', { flag: ['gh.registry', 'gh.depot_file'], rep: { court: -5 }, infamy: 2 })),
    C('Refuse, loudly', O('You tore up the form in front of the queue. Half of them followed you out of the square. All of you are outlaws now.', { flag: ['gh.registry', 'gh.outlaw'], rep: { court: -15, orthodox: 6 }, fame: 4, infamy: 4 })),
  ] }),
  E('gh_beggar_halls', 'timeline', { if: { happened: 'beggars_outlawed', loc: 'luoyang', year: [57, 61], age: [14, 120] }, danger: true, art: 'fire', title: 'The bridges burn', text: 'The Depot is burning the Beggars’ Sect out from under the bridges of Luoyang. Smoke over the river, and children in patched coats running through it in every direction.', choices: [
    C('Get the children out', O('You carried children out of the smoke until your eyes stopped working. Then the old beggars took them, one by one, into the city’s cellars, where the Depot would never think to look.', { fame: 5, rep: { orthodox: 6, court: -6 }, health: -10, sanity: 3 })),
    C('Fight the Depot men at the bridge', O('A Depot officer turned at the bridge with his saber already moving.', { combat: { foe: { name: 'a Depot officer', kind: 'soldier', rel: 0 }, context: 'war', lethal: 0.3, win: { text: 'The officer went into the river. Behind you, a line of beggars crossed the bridge and vanished into Luoyang.', fame: 5, rep: { orthodox: 8, court: -12 }, infamy: 2 }, lose: { text: 'You went into the river. Somebody in patches fished you out downstream and never told you their name.', rep: { orthodox: 3 } } } })),
    C('Keep your head down', O('You kept your head down and watched it burn. When it was over the bridges were very quiet, and the city felt like a house with the dogs taken away.', { sanity: -6 })),
  ] }),
  E('gh_coup_night', 'timeline', { if: { loc: 'capital', year: [60, 60], season: [1, 2], flag: 'w.registry', alive: ['depot_director', 'guard_commander'], age: [16, 120] }, art: 'palace', title: 'Horses in the palace stables', text: 'The Eastern Depot has been buying horses all year, and tonight the Depot stables are full and saddled. In a teahouse by the palace gate, Han Gyeong, Commander of the Imperial Guard, is drinking alone, as he does every night, looking tired.', choices: [
    C('Sit down and tell him about the horses', O('He listened without moving. “I know about the horses,” he said at last. “I did not know anyone else had noticed.” He left his tea half-finished. You have a feeling it will be a long autumn.', { meet: '@guard_commander', rel: { '@guard_commander': { res: 20, aff: 10 } }, rep: { court: 3 } })),
    M('Tell him which gate, and which night', 'timeline.depot_coup', O('You told him: the palace steps, the last night of autumn. He looked at you as if you were a ghost. “Then we will be standing on the steps,” he said.', { meet: '@guard_commander', rel: { '@guard_commander': { res: 30 } }, rep: { court: 6 }, fame: 3 })),
    C('Leave the capital', O('You left before the autumn ended. Capitals change hands in the dark, and the dark is never particular about who it catches.', { travel: 'paeng' })),
  ] }),

  // Years 78–120: the long view
  E('gh_quake_signs', 'timeline', { if: { region: 'shu', year: [78, 80], age: [14, 200], timeline: { shu_quake: 'pending' } }, art: 'mountain', title: 'The wells of Shu', text: 'In Shu the wells have started to boil without fire, and the frogs have left the paddies in their thousands, all walking east. The old women say the dragon under Mount Qingcheng is turning over in its sleep.', choices: [
    M('You remember the autumn of year 80', 'timeline.shu_quake', O('You went from magistrate to magistrate, sect to sect, with the dates. Most laughed. Enough listened: when the earth split, the Chengdu markets were empty and half the city was sleeping in the fields.', { flag: 'gh.quake_warned', fame: 15, gaze: 1, rep: { orthodox: 4, court: 4 } })),
    R('Convince the Qingcheng Sect to sleep outdoors', 'fame', 45, O('The Qingcheng elders humoured you, grumbling, and slept a season under the pines. When the peak fell, the halls were empty.', { flag: 'gh.quake_warned', fame: 8, rep: { orthodox: 6 } }), O('Qingcheng does not take advice from outsiders. It never has.', { rep: { orthodox: -1 } })),
    C('Follow the frogs', O('You followed the frogs east for a week. It seemed as good a plan as any. The old women nodded as you passed.', { travel: 'wuchang', codex: 'timeline.shu_quake' })),
  ] }),
  E('gh_quake_warned_after', 'timeline', { if: { happened: 'shu_quake', flag: 'gh.quake_warned', region: 'shu', year: [80, 85], age: [14, 200] }, art: 'temple', title: 'The people who slept in the fields', text: 'Chengdu rebuilds. In the market, an old woman you have never met presses a boiled egg into your hand. “You told my son to sleep in the fields,” she says. “He did. He has three children.”', choices: [
    C('Eat the egg', O('You ate the egg on the rubble of the old market, with the old woman watching to make sure you finished it. Some rewards are exactly the right size.', { sanity: 10, fame: 2 })),
    C('Ask how many were saved', O('Nobody counted the living; only the dead get counted. But the magistrate said it was the lightest earthquake in the records, considering, and nobody could explain why.', { sanity: 5, insight: 1 })),
  ] }),
  E('gh_century_guest', 'timeline', { if: { loc: 'luoyang', year: [99, 100], realm: '>=5', age: [40, 300] }, art: 'tournament', title: 'An invitation for the Century', text: 'A runner in Alliance blue finds you with a lacquered invitation: the Century Assembly will seat every living master of the Transcendent realm and above. Your name is on the list, spelled wrong.', choices: [
    C('Attend', O('You sat among old men and women who had once been terrifying, and were now mostly talking about their knees. One of them had tried to kill you, fifty years ago. He did not remember. You did.', { fame: 6, rep: { orthodox: 4 }, sanity: 3, codex: 'timeline.century_assembly' })),
    C('Correct the spelling and stay home', O('You sent the invitation back with the spelling corrected. The Alliance sent it back with the spelling corrected wrong in a new way.', { charm: 1, sanity: 2 })),
  ] }),
  E('gh_tomb_ice', 'timeline', { if: { happened: 'kunlun_tomb', loc: 'kunlun', realm: '>=5', age: [20, 400], noManual: 'lost_heaven_earth' }, danger: true, art: 'cave', title: 'The tomb in the ice', text: 'The tomb the glacier opened is sealed by Kunlun edict and guarded by Kunlun disciples who are, at this hour, mostly asleep. The ice door is carved with two hands meeting.', choices: [
    M('Press the door where the hands meet', 'timeline.kunlun_tomb', O('You knew how. The door opened like a breath. Inside, on a table of ice, a single scroll: the Heaven and Earth Harmony Art. You read it until dawn and walked out with it in your head instead of your hands.', { manual: 'lost_heaven_earth', insight: 4, gaze: 1, rep: { orthodox: -4 } })),
    R('Break the seal', 'power', 120, O('You broke the seal with your bare qi. The tomb was empty except for frost and a scroll you could barely read. Enough. You came out changed.', { qi: 30, insight: 3, rep: { orthodox: -8 }, infamy: 3 }), O('The seal broke you instead. The Kunlun disciples found you at dawn, frozen to the door by one hand.', { health: -35, rep: { orthodox: -6 } })),
    C('Leave the dead their sleep', O('You bowed to the door and walked down the mountain. Not every door is yours.', { sanity: 3 })),
  ] }),
];

// ── Templates: the Gangho ─────────────────────────────────────────────
// City life: one everyday scene for every place on the map. Each row has its own stakes, roll and reward.
const tplCity = template('gh_city', [
  { key: 'willow', loc: 'willow', age: [8, 80], if: { season: 0 }, art: 'garden', title: 'Planting season', text: 'Spring in Willow Creek, and every back in the village is bent over the paddies. Granny Seo’s sons have all gone to the city; hers is the only field still unplanted.',
    main: R('Plant it for her', 'body', 14, O('You planted her field in two days, knee-deep in cold mud. She paid you in pickled radish and gossip, both very strong.', { body: 1, sanity: 4 }), O('By the second day your back seized like a rusted hinge. Granny Seo finished the row herself, faster than you.', { health: -4, charm: 1 })),
    alt: C('Mind the village children so their parents can work', O('You minded eleven children for a week. You have fought bandits who frightened you less.', { charm: 1, sanity: 2 })) },
  { key: 'mounthua', loc: 'mounthua', age: [12, 80], art: 'mountain', title: 'The chain path', text: 'On the cliff path below the peaks, a sightseer from the capital has frozen on the iron chains with a thousand feet of air beneath his silk shoes. His servants are wailing at the bottom.',
    main: R('Climb down to him', 'body', 22, O('You climbed down, talked about his dinner plans and walked him up one chain at a time. He pressed a silver ingot into your hand and fainted.', { wealth: 10, fame: 2, rep: { orthodox: 1 } }), O('You reached him and froze too. A Mount Hua junior climbed down eating a peach and walked you both up without comment.', { fame: -1, rep: { orthodox: 1 } })),
    alt: C('Fetch someone from the sect', O('The one who came down was Granny Pyo, the sect cook, with a basket of turnips on her back. She plucked the man off the chains like a cabbage.', { meet: '@hua_cook', sanity: 2 })) },
  { key: 'changan', loc: 'changan', age: [12, 80], art: 'market', title: 'The Western Market', text: 'In Chang’an’s Western Market a spice-seller’s scales tilt the wrong way for every customer who cannot read numbers, which is most of them.',
    main: R('Weigh his weights in front of the crowd', 'insight', 20, O('You weighed his weights against a purse of known coin. He closed his stall with great dignity and fled.', { fame: 1, rep: { merchants: -1 }, sanity: 2 }), O('He sold you saffron that turned out to be dyed sawdust. You were furious, and slightly impressed.', { wealth: -3 })),
    alt: C('Buy a lamb skewer and watch', O('The skewer was excellent. The spice-seller made eleven taels while you ate it.', { wealth: -1, health: 2 })) },
  { key: 'zhongnan', loc: 'zhongnan', age: [12, 80], art: 'forest', title: 'Three hundred steps', text: 'A Zhongnan hermit asks you to carry water up the three hundred steps to his hermitage, twice a day, for a week. He does not say why. He does not say thank you.',
    main: R('Carry the water', 'body', 20, O('By the seventh day the buckets were weightless, and so, almost, were you. The hermit poured the last bucket over a stone and said, “Good. Now you know how.”', { qi: 10, body: 1 }), O('On the third day you dropped both buckets. The hermit watched them bounce all the way to the bottom and laughed for an hour.', { health: -3, sanity: 1 })),
    alt: C('Argue with him about the Dao', O('You argued for a week. He won every argument by not answering. You came down wiser and annoyed.', { insight: 2, sanity: -1 })) },
  { key: 'kongtong', loc: 'kongtong', age: [14, 80], art: 'snow', title: 'The coughing disciple', text: 'Behind the Kongtong training ground a young disciple is coughing blood into the snow. The Seven Injuries Fist wounds its user as much as its target, and he has been practising it in secret. He begs you not to tell his master.',
    main: R('Treat him yourself', 'insight', 26, O('You knew enough medicine to calm his meridians and enough sense to make him promise to stop. He kept the promise, mostly. Kongtong remembers favours.', { rep: { orthodox: 3 }, insight: 1 }), O('You made it worse. His master found you both and was grateful to neither.', { rep: { orthodox: -2 }, sanity: -2 })),
    alt: C('Tell his master anyway', O('His master thanked you coldly and confined the boy for a season. He will live. He will not forgive you.', { rep: { orthodox: 1 }, sanity: -1 })) },
  { key: 'luoyang', loc: 'luoyang', age: [10, 80], art: 'city', title: 'Court under the bridge', text: 'Under the Tianjin Bridge the Beggars’ Sect is holding a trial: a one-pouch beggar accused of stealing another’s bowl. Neither elder wants to judge it, so they ask the stranger.',
    main: R('Judge it', 'insight', 22, O('You noticed the bowl’s chip matched the accuser’s thumb, not the accused’s. The beggars applauded, which in their court is a verdict.', { rep: { orthodox: 3 }, fame: 1 }), O('Your verdict satisfied nobody. Both beggars spat in your bowl, and you did not even have a bowl.', { charm: -1 })),
    alt: C('Buy them each a new bowl', O('Two bowls, a copper each. The trial ended in a feast. Beggars are practical people.', { wealth: -1, rep: { orthodox: 1 }, sanity: 2 })) },
  { key: 'songshan', loc: 'songshan', age: [12, 80], art: 'temple', title: 'Blessings for sale', text: 'At the foot of Mount Song a “monk” with a suspiciously fresh shave sells Shaolin blessings to pilgrims: three coppers for health, ten for a son, fifty for martial arts.',
    main: R('Ask him which sutra the blessing comes from', 'charm', 22, O('He named a cookbook. The pilgrims chased him halfway to Luoyang.', { rep: { orthodox: 2 }, fame: 1 }), O('He blessed you for free, as a professional courtesy. Then a real monk chased you both off.', { rep: { orthodox: -1 } })),
    alt: C('Buy the martial arts blessing', O('Fifty coppers. You felt exactly the same. Real monks passing by looked at you with infinite compassion.', { wealth: -1, sanity: 2 })) },
  { key: 'kaifeng', loc: 'kaifeng', age: [12, 80], art: 'market', title: 'Cricket fights', text: 'In a Kaifeng alley a crowd is screaming at two crickets in a clay pot. The favourite is called General Iron Jaw. The other has no name and five legs.',
    main: R('Study the crickets, then bet', 'insight', 24, O('The five-legged one held its antennae like a duellist. You bet on it and won a month’s rent.', { wealth: 10, insight: 1 }), O('General Iron Jaw ate your cricket. You do not want to talk about it.', { wealth: -5 })),
    alt: C('Buy the five-legged cricket and set it free', O('You let it go in a garden. It was probably eaten. You told yourself it was not.', { wealth: -1, sanity: 3 })) },
  { key: 'wudang', loc: 'wudang', age: [10, 90], art: 'mountain', title: 'Dawn in the foothills', text: 'At dawn in the Wudang foothills, a crowd of old men and women move through the Taiji forms together, slow as clouds. A grandmother pats the space beside her.',
    main: R('Move with them', 'sanity', 50, O('You moved with them for an hour. Something in your chest unknotted that you had not known was knotted.', { qi: 12, sanity: 4 }), O('You fell asleep standing up, which the grandmother said was also correct, in its way.', { sanity: 3 })),
    alt: C('Do the forms at full speed to show them', O('You did the forms four times faster. The old people watched politely. One said, “Young people are so tired.”', { body: 1, charm: -1 })) },
  { key: 'wuchang', loc: 'wuchang', age: [14, 70], art: 'river', title: 'A split crate', text: 'Unloading on the Wuchang docks, a crate splits open: salt, packed under tea, which means somebody is not paying the salt tax. The foreman sees you see it.',
    main: R('Negotiate your silence', 'charm', 26, O('The foreman paid generously for your poor eyesight. You felt richer and slightly more crooked.', { wealth: 18, infamy: 2 }), O('The foreman’s friends explained the value of silence with their knuckles.', { health: -8 })),
    alt: C('Report it to the harbour office', O('The harbour officer seized the salt and, as far as you could tell, sold it himself.', { rep: { court: 2, unorthodox: -2 } })) },
  { key: 'dongting', loc: 'dongting', age: [14, 70], art: 'lake', title: 'The lake ghost', text: 'A Dongting fisherman says a lake ghost keeps tearing his nets in the deep channel. His children are hungry and the Water Fortress still wants its toll.',
    main: R('Dive the channel', 'body', 28, O('No ghost: an old wreck full of snagged nets, and in the mud a rusted saber still sharp enough to cut them. You cleared the channel and kept the saber.', { item: { heavy_saber: 1 }, fame: 1 }), O('The cold took your breath at the bottom. You came up blue and empty-handed, and the fisherman had to fish you out instead.', { health: -10 })),
    alt: C('Pay his toll for the season', O('You paid. He wept. The toll-taker gave you an odd look, as if generosity were a kind of smuggling.', { wealth: -3, sanity: 3 })) },
  { key: 'chengdu', loc: 'chengdu', age: [12, 80], art: 'city', title: 'The opera needs a sword', text: 'A Sichuan opera troupe’s stage swordsman has run off with the face-changer’s wife. The show starts in an hour. The manager grabs your sleeve.',
    main: R('Go on stage', 'body', 18, O('You fought six demons and a dragon made of four men. The crowd threw coins. The face-changer, heartbroken, gave his best show in years.', { wealth: 4, fame: 2, charm: 1 }), O('You fell into the orchestra in the second act. The audience agreed it was the best part.', { charm: -1, sanity: 3 })),
    alt: C('Have your ears cleaned in a teahouse instead', O('A Chengdu ear-cleaner with silver tools and a feather. For a quarter of an hour you forgot every grudge you have ever held.', { wealth: -1, sanity: 5 })) },
  { key: 'emei', loc: 'emei', age: [12, 80], art: 'temple', title: 'The monkeys of Emei', text: 'On the Emei pilgrim path a monkey snatches your bag and sits on a rock just out of reach, going through it with great interest.',
    main: R('Chase it', 'body', 20, O('You chased it up three terraces and a tree. It dropped the bag and stole your hat instead, which you count as a draw.', { body: 1 }), O('It led you in circles for an hour, then threw your bag into a gorge.', { wealth: -4, sanity: -1 })),
    alt: C('Offer it a peach', O('The monkey took the peach, considered, and returned your bag. The nuns say it is the only monkey on Emei with manners.', { sanity: 2 })) },
  { key: 'qingcheng', loc: 'qingcheng', age: [14, 80], art: 'forest', title: 'An old insult', text: 'Two Qingcheng disciples stop you in a mountain village. Thirty years ago a man with your family name insulted their grand-master at a wedding. They would like to know if you are related.',
    main: R('Explain, at length, that you are not', 'charm', 28, O('You recited your family tree back six generations until they begged you to stop. One of them bought you tea out of pity.', { rep: { orthodox: 2 }, charm: 1 }), O('They were not convinced. They slapped you with the flats of their swords, very formally, and wrote your name down.', { health: -5, flag: 'gh.qingcheng_grudge', rep: { orthodox: -2 } })),
    alt: C('Apologise on your family’s behalf', O('You apologised for something you did not know about, done by someone you never met. They accepted. Qingcheng grudges are long, but Qingcheng loves an apology.', { rep: { orthodox: 1 }, sanity: -1 })) },
  { key: 'dangclan', loc: 'dangclan', age: [14, 70], art: 'garden', title: 'Herb pickers wanted', text: 'The Dang family’s outer gardens hire day labourers to pick herbs. Gloves are provided. The overseer says they are “mostly” enough.',
    main: R('Pick carefully', 'insight', 30, O('You learned which leaves to touch and which to cut with a knife. At dusk the overseer paid you and, unusually, explained a recipe.', { wealth: 8, recipe: 'healing_salve' }), O('You touched the wrong leaf. Your hand swelled like a melon for a week.', { health: -12, wealth: 2 })),
    alt: C('Watch the other pickers', O('An old woman picked twice as fast as anyone, with no gloves at all. She winked at you. You decided not to ask.', { insight: 1 })) },
  { key: 'diancang', loc: 'diancang', age: [12, 80], art: 'mountain', title: 'Falling leaves', text: 'A Diancang swordsman in the southern market cuts falling leaves in half before they touch the ground, for coins. He bets you cannot catch one before he cuts it.',
    main: R('Take the bet', 'body', 32, O('You caught a leaf a hair before his blade. He stared, laughed and paid double. “Come up the mountain,” he said. “We need people who are faster than they look.”', { fame: 2, wealth: 4, rep: { orthodox: 2 } }), O('He cut the leaf between your fingers. You did not feel it until you saw the two halves.', { wealth: -2, insight: 1 })),
    alt: C('Ask him how', O('“Do not watch the leaf,” he said. “Watch the wind.” It sounded like nonsense. It is not.', { insight: 2 })) },
  { key: 'namgung', loc: 'namgung', age: [12, 80], art: 'estate', title: 'Commoners at the gate', text: 'Outside the Namgung Estate a cousin of the main line is mocking the commoners who wait with petitions, reading their letters aloud in silly voices.',
    main: R('Mock him back, politely', 'charm', 26, O('You praised his reading so lavishly his own cousins began laughing at him. He stalked inside. Several petitioners bowed to you.', { rep: { families: -1 }, fame: 2 }), O('He had his retainers throw your petition, which you did not have, into the moat.', { rep: { families: -2 } })),
    alt: C('Bow and wait your turn', O('You bowed and waited. Face is a currency, and you are saving yours for later.', { rep: { families: 2 }, sanity: -2 })) },
  { key: 'hangzhou', loc: 'hangzhou', age: [12, 70], if: { season: 3 }, art: 'lake', title: 'Year-end at the counting house', text: 'At the year’s end the Golden Abacus counting houses hire anyone who can use an abacus to close the books. The clatter can be heard across West Lake.',
    main: R('Work the books', 'insight', 22, O('Three nights of beads and ledgers. You found forty taels missing that turned out to be the Guild Master’s tea budget. They paid you and asked you back.', { wealth: 10, rep: { merchants: 3 } }), O('You moved one bead wrong and spent two nights finding it.', { wealth: 2, sanity: -2 })),
    alt: C('Take a boat out on the lake instead', O('Snow on West Lake, and the broken bridge that is not broken. You wrote a terrible poem about it.', { sanity: 4 })) },
  { key: 'capital', loc: 'capital', age: [12, 80], if: { season: 0 }, art: 'palace', title: 'Lanterns', text: 'The Lantern Festival in the capital: ten thousand lanterns, a riddle on every one, and Depot agents in plain clothes trying not to look at anyone in particular.',
    main: R('Count the agents', 'insight', 28, O('You counted thirty-one. One noticed you counting, smiled and raised his cup. You have never felt so thoroughly seen.', { insight: 2, flag: 'gh.depot_file' }), O('You decided the man behind you was an agent and lost him in the crowd. He was a dumpling seller who wanted paying.', { charm: -1, wealth: -1 })),
    alt: C('Solve the lantern riddles', O('Nine riddles and a paper rabbit. It is the most honest prize in the capital.', { insight: 1, sanity: 4 })) },
  { key: 'paeng', loc: 'paeng', age: [14, 80], art: 'feast', title: 'The wrestling feast', text: 'The Paeng family is holding a feast where every guest must wrestle a Paeng to earn a seat. The current champion is eating a whole goose between bouts.',
    main: R('Wrestle the champion', 'body', 30, O('You threw him over the goose. The hall roared, the champion loudest. You ate at the high table and went home with a jar of their wine.', { item: { rice_wine: 1 }, rep: { families: 3 }, fame: 1 }), O('He threw you into the goose. They gave you a seat anyway, for the entertainment.', { health: -3, rep: { families: 1 } })),
    alt: C('Try to out-eat him instead', O('Nobody has ever out-eaten a Paeng. They admired the attempt enormously.', { health: 2, rep: { families: 1 }, charm: 1 })) },
  { key: 'jegal', loc: 'jegal', age: [10, 80], art: 'library', title: 'Baduk in the library', text: 'In the Jegal library garden a girl of nine is playing baduk against all comers. She is winning. She is also reading a book with her other hand.',
    main: R('Play her', 'insight', 36, O('You held her to a close game. She looked up from her book for the first time. “Again,” she said. You lost the second game in forty moves and learned more than in a year.', { insight: 3, rep: { families: 2 } }), O('She beat you without looking up. Then she explained why, which was worse.', { insight: 1, sanity: -1 })),
    alt: C('Ask what she is reading', O('“A history of everyone who lost to my grandfather,” she said. “It is very long.”', { charm: 1 })) },
  { key: 'taihang', loc: 'taihang', age: [14, 70], art: 'market', title: 'The bandit market', text: 'Deep in the Taihang, a market where everything for sale was stolen from somebody else last week. A fine sword is going cheap, with someone’s family crest still on the hilt.',
    main: R('Sell them news of the escort roads', 'charm', 26, O('The Green Forest pays well for news. You told them about the slow caravans, not the poor ones.', { wealth: 12, rep: { unorthodox: 3 }, infamy: 2 }), O('They already knew. They charged you for wasting their time.', { wealth: -4 })),
    alt: C('Just look around', O('You found your own stolen boots from three years ago and bought them back. They still fit.', { wealth: -2, sanity: 2 })),
    more: [Q('Buy the crested sword (15 taels)', { stat: { wealth: '>=15' } }, O('A fine blade at a third of its price. You filed off somebody’s grandfather’s crest. Mostly.', { wealth: -15, item: { fine_sword: 1 }, infamy: 1 }))] },
  { key: 'moyong', loc: 'moyong', age: [12, 80], if: { season: 3 }, art: 'snow', title: 'Ice fishing', text: 'In the Liaodong winter the sea itself freezes near the shore. Moyong servants cut holes in the ice and fish in silence, as courteous to the fish as to everything else.',
    main: R('Fish with them', 'body', 26, O('You sat on the ice until your eyebrows froze, and caught a fish as long as your arm. The servants bowed to it, then to you.', { health: 3, rep: { families: 1 }, sanity: 2 }), O('The ice cracked under you. A Moyong servant pulled you out by the collar without a word and went back to fishing.', { health: -10 })),
    alt: C('Watch the Moyong heir practise on the ice', O('A girl in white turned on the ice with her eyes closed, catching snowflakes on the flat of her sword and sending them back into the wind. Return to Sender, the Moyong call it.', { insight: 2 })) },
  { key: 'kunlun', loc: 'kunlun', age: [14, 90], art: 'snow', title: 'A pilgrim in the snow', text: 'Below the Kunlun gate a pilgrim lies in the snow, alive, barely. The storm is getting worse and the gate is a long climb.',
    main: R('Carry him up', 'body', 30, O('You carried him the whole way, step by frozen step. The gatekeeper took him in and looked at you with something close to respect, which on Kunlun is a festival.', { fame: 2, rep: { orthodox: 3 }, health: -6 }), O('Halfway up you had to dig a snow cave. You both lived. A Kunlun disciple found you in the morning, unimpressed.', { health: -12, rep: { orthodox: 1 } })),
    alt: C('Run for help', O('The gatekeeper came down with a sled and no expression. The pilgrim lived. Nobody asked your name.', { rep: { orthodox: 1 } })) },
  { key: 'jadegate', loc: 'jadegate', age: [14, 80], art: 'desert', title: 'Three water-sellers', text: 'At the Jade Gate market a camel trader will give you a share of his next caravan if you can tell him which of his three water-sellers is cheating him.',
    main: R('Watch them work', 'insight', 26, O('The one with the heaviest skins had the thinnest arms. The trader paid you and drew you a map of the oasis roads.', { wealth: 15, rep: { merchants: 2 } }), O('You picked an honest man. The trader stopped speaking to you.', { sanity: -3 })),
    alt: C('Buy dried melon and watch the caravans', O('The caravans came and went, bells ringing, bound for places whose names you could not pronounce. You felt very small and very lucky.', { wealth: -1, sanity: 3 })) },
  { key: 'tenthousand', loc: 'tenthousand', age: [12, 80], art: 'demonic', title: 'The Hall of Strength', text: 'In the Ten Thousand Mountains any believer may climb into the Hall of Strength ring and fight for a better rank. Today a farmer’s daughter is beating an officer, and the crowd is losing its mind.',
    main: R('Climb into the ring yourself', 'body', 30, O('You won two bouts and lost the third with honour. In the Cult, that is worth more than a letter of recommendation.', { rep: { cult: 5 }, fame: 1, health: -5 }), O('You lost the first bout in a breath. A Demon Warrior dusted you off. “Again next month,” he said. It was not a suggestion.', { rep: { cult: 1 }, health: -8 })),
    alt: C('Cheer for the farmer’s daughter', O('She won. She looked straight at you in the crowd, the only one shouting her name before the end, and nodded.', { rep: { cult: 2 }, sanity: 2 })) },
], (r) => E('gh_city', 'jianghu', { if: { loc: r.loc, age: r.age, ...(r.if || {}) }, once: false, cd: 5, art: r.art, title: r.title, text: r.text, choices: [r.main, r.alt, ...(r.more || [])] }));

// Tavern rumours of the Gangho: buy another cup, press for more, or leave. Many carry foreknowledge.
const tplTavern = template('gh_tavern', [
  { key: 'willow', loc: 'willow', if: { year: [11, 15] }, title: 'The miller’s gossip', text: 'In the Willow Creek wine-shop the miller says a man with a saber wrapped in red cloth came through last month, asking how many men the village has and which road the harvest carts take.',
    pour: O('Another cup, and the miller remembered more: a scar through one eyebrow, and he came down the north road from the Taihang.', { codex: 'timeline.willow_raid' }),
    press: R('Ask the chief to post a watch on the north road', 'charm', 18, O('Chief Yun agreed, grumbling about the cost of torches. It is a start.', { meet: '@village_chief', fame: 1, sanity: 2 }), O('Chief Yun said bandits never come this far south. He said it twice, as if to convince himself.', { meet: '@village_chief' })),
    leave: O('You finished your cup. The miller moved on to his knees.') },
  { key: 'changan', loc: 'changan', title: 'Where the Saint drinks', text: 'A drunk old courier in a Chang’an wine-house swears he has delivered wine to the Drunken Sword Saint in four different places over forty years, “and every time he was further from home.”',
    pour: O('For another cup he listed them: Luoyang, Lake Dongting, Mount Hua, and at the very end the Kunlun ice. A decade in each, give or take a hangover.', { codex: { id: 'secret.gh_saint_trail', cat: 'secrets', title: 'Where the Saint drinks', text: 'The Drunken Sword Saint wanders by decade: Luoyang in years 10–19, Lake Dongting in years 20–29, Mount Hua in years 30–39, the Kunlun ice from year 40 until he dies.' } }),
    press: R('Ask what the Saint drinks', 'insight', 24, O('“Bamboo-leaf green, from Fenzhou,” the courier said, “and never once paid for.” You wrote it down.', { insight: 1, flag: 'gh.saint_wine' }), O('He described a wine that does not exist and fell asleep in his bowl.')),
    leave: O('You left him snoring. Chang’an is full of men who once delivered something to someone famous.') },
  { key: 'luoyang', loc: 'luoyang', title: 'The second ledger', text: 'Two Alliance clerks drinking off duty complain about the accounts: the treasury always comes up short at the year’s end, and the Leader’s steward always has the missing amount in a second ledger nobody may see.',
    pour: O('Another cup, and the younger clerk whispered where the second ledger lives: a lacquer box in the Leader’s study, under a bundle of letters.', { codex: { id: 'secret.gh_second_ledger', cat: 'secrets', title: 'The second ledger', text: 'Hwangbo Jun’s steward keeps a second ledger in a lacquer box in the Leader’s study in Luoyang, under a bundle of letters. The treasury’s missing silver is in it, and perhaps more.' } }),
    press: R('Offer to take the ledger off their hands', 'charm', 28, O('They laughed nervously and changed the subject, but the elder gave you his name, in case you ever needed a friend in the Alliance offices.', { rep: { orthodox: 1 }, insight: 1 }), O('They went pale and left without paying. You paid.', { wealth: -2 })),
    leave: O('You left them to their arithmetic.') },
  { key: 'kaifeng', loc: 'kaifeng', if: { year: [20, 23] }, title: 'A big contract', text: 'In a Kaifeng gambling den a Ghost Market broker is drunk and boasting: the Blood Shadow Pavilion has taken the biggest contract in ten years, for a man “who has never been afraid of anything in his life.”',
    pour: O('Another cup, and the broker giggled out the rest: winter, a study, a roof. “Namgung men never look up,” he said.', { codex: 'timeline.namgung_assassination' }),
    press: R('Find out who is paying', 'insight', 30, O('Jegal gold, through a Kaifeng moneylender named Cha. You memorised his face.', { codex: { id: 'secret.gh_jegal_gold', cat: 'secrets', title: 'Jegal gold', text: 'The Blood Shadow contract on Namgung Hwi in year 23 is paid in Jegal gold, through a Kaifeng moneylender named Cha who keeps his ledgers inside a hollow Buddha.' } }), O('The broker sobered up enough to wonder why you cared.', { sanity: -2 })),
    leave: O('You left. The dice kept rolling behind you, like history.') },
  { key: 'wuchang', loc: 'wuchang', if: { year: [10, 13] }, title: 'Chains across the narrows', text: 'Boatmen in a Wuchang tavern grumble that the Water Fortress has been stretching iron chains across the narrows below Dongting at night, “for practice,” and charging the boats that hit them.',
    pour: O('Another cup, and an old boatman said what the others would not: chains like that are not for tolls. They are for sinking something big. Like a grain fleet.', { codex: 'timeline.grain_fleet' }),
    press: R('Ask who forges the chains', 'charm', 22, O('A smith in Hanyang who drinks here on fast days. He was more frightened of the Fortress than of you, but not by much.', { insight: 1, rep: { unorthodox: -1 } }), O('The boatmen suddenly remembered boats that needed seeing to.')),
    leave: O('You left. Out on the river the lanterns were very far apart.') },
  { key: 'chengdu', loc: 'chengdu', if: { year: [21, 25] }, title: 'The second son’s shopping', text: 'An apothecary drinking in Chengdu complains about a Dang customer: the matriarch’s second son, buying a tasteless herb in amounts that would kill a horse, “and he does not keep horses.”',
    pour: O('Another cup, and he named it: grey-heart moss, which does nothing at all in tea, unless you add a drop of Dang lacquer.', { codex: 'timeline.dang_civil_war' }),
    press: R('Ask how to tell if tea has been touched', 'insight', 30, O('“Silver turns grey, everyone knows that,” he said. “The Dang know everyone knows. So they use something else.” He told you what, and what shows it.', { codex: { id: 'secret.gh_grey_heart', cat: 'secrets', title: 'Grey-heart moss', text: 'Grey-heart moss and a drop of Dang lacquer make a tea poison that silver cannot find. Dang Gwang buys the moss in Chengdu in years 21–25. A jade spoon clouds in it.' } }), O('He realised he had said too much, and that you were listening.', { sanity: -1 })),
    leave: O('You left him muttering about horses.') },
  { key: 'hangzhou', loc: 'hangzhou', if: { year: [14, 17] }, title: 'Buying up the rope', text: 'Silk merchants in a Hangzhou teahouse complain that the Golden Abacus Guild has been quietly buying every small shop’s debts, one at a time, “like a man buying all the rope in town.”',
    pour: O('Another cup: the Guild means to call them all in on one day, in the winter of the seventeenth year, and buy the shops for nothing.', { codex: 'timeline.merchant_ruin' }),
    press: R('Ask which debts are already bought', 'charm', 28, O('They named a dozen shops. You can buy a debt back if you reach the creditor before the Guild does, they said, and if you have the silver, which nobody does.', { rep: { merchants: 1 }, insight: 1, flag: 'gh.knows_debts' }), O('They decided you were a Guild spy and talked about the weather.', { rep: { merchants: -1 } })),
    leave: O('You left. The lake was very calm, the way water is before it closes over something.') },
  { key: 'capital', loc: 'capital', if: { year: [18, 21] }, title: 'The clerk who forges', text: 'A Depot clerk named Mun is drunk in an officials’ teahouse, boasting that he can copy any man’s handwriting so well the man himself would sign it.',
    pour: O('Another cup, and Mun showed you: your name, in your own hand, after watching you sign the bill once. “Treason letters are just letters,” he laughed.', { codex: 'timeline.father_framed' }),
    press: R('Find out whose hand he is practising', 'insight', 32, O('He let slip a name, a Ministry official to be arrested “the autumn after next,” and patted his sleeve, where the practice sheets were.', { codex: { id: 'secret.gh_mun_forger', cat: 'secrets', title: 'Mun the forger', text: 'Mun, a Depot clerk, forges treason letters in the hands of honest officials. He keeps his practice sheets in his left sleeve and drinks at the Willow Bridge teahouse every tenth day. Caught with them, he confesses.' } }), O('He grew suspicious and talked about his mother instead.')),
    leave: O('You left. Behind you Mun was signing the Emperor’s name on a napkin, for fun.') },
  { key: 'jadegate', loc: 'jadegate', if: { year: [25, 28] }, title: 'Boxes for the west', text: 'Caravan drivers at a Jade Gate tavern swap stories. One has been hired three times to carry sealed Dang boxes to the Ten Thousand Mountains, “for the Blood Faction’s physicians, who must be very ill.”',
    pour: O('Another cup: the Blood Faction pays in Cult gold and says the boxes are for an old man’s cough. “Funny,” the driver said. “Coughs don’t usually need guards.”', { codex: 'timeline.demon_poisoned' }),
    press: R('Ask what the boxes look like', 'charm', 26, O('“Black wax, red thread round every phial. End of summer, every year.” He did not seem to think it was a secret.', { codex: 'secret.gh_poison_road' }), O('He decided you were a Cult spy, which made two of you suspicious of each other.', { rep: { cult: -1 } })),
    leave: O('You left. Westward, the road was a pale line into the dark.') },
  { key: 'tenthousand', loc: 'tenthousand', if: { year: [26, 29] }, title: 'A toast to the new spring', text: 'In a Cult barracks canteen young officers of the Blood Faction are toasting “the new spring,” and laughing at something the rest of the room does not understand.',
    pour: O('You bought a round. A drunk officer told you, grinning, that the old man will not see another winter and the girl will not see another spring.', { codex: 'timeline.cult_coup' }),
    press: R('Find out where they will strike', 'insight', 32, O('The Hall of Ten Thousand Demons, the first day of spring, while the Young Heavenly Demon is at prayer. They were very proud of the timing.', { codex: { id: 'secret.gh_coup_hall', cat: 'secrets', title: 'The east door', text: 'The Blood Faction’s coup in year 29 strikes in the Hall of Ten Thousand Demons on the first day of spring, while Dan Ha-ryeong is at prayer. A bribed guard leaves the east door unbarred.' } }), O('They stopped laughing and asked who your commander was.', { rep: { cult: -2 } })),
    leave: O('You left before anyone asked your name.') },
  { key: 'dongting', loc: 'dongting', title: 'The fisherman with no bait', text: 'Pirates in a Dongting tavern argue about the old fisherman who fishes the deep channel with no bait and no hook. Every one of them has tried to rob him. Every one of them woke up in the reeds.',
    pour: O('Another cup: the Water Lord himself once tried, they say, and came back a week later with white hair, and never spoke of it.', { codex: 'people.fisherman' }),
    press: R('Ask where he fishes', 'charm', 24, O('“The deep channel at dawn. Do not take a weapon. He does not like weapons.”', { flag: 'gh.fisherman_where', insight: 1 }), O('They told you to find out yourself, the way they had.')),
    leave: O('You left. Out on the lake, very far off, a single punt sat perfectly still.') },
  { key: 'taihang', loc: 'taihang', title: 'The Tiger’s rules', text: 'Green Forest bandits in a mountain tavern are reciting the Mountain Tiger’s rules to a new recruit, who keeps getting them wrong.',
    pour: O('Another cup, and they told you the first rule, the one the Tiger will kill you for breaking: never rob a healer, nor anyone carrying medicine to the sick.', { codex: { id: 'secret.gh_tiger_code', cat: 'secrets', title: 'The Mountain Tiger’s first rule', text: 'Green Forest bandits will not rob a healer or anyone carrying medicine to the sick. Show a medicine pouch and name the rule, and most of them will let you pass.' } }),
    press: R('Ask about the Blood Blade Ghost', 'charm', 26, O('The table went quiet. “Pi Mun breaks the rules,” one finally said. “The Tiger has sworn to hang him one day.”', { codex: 'people.blood_blade' }), O('Nobody would speak of him. Even bandits have names they do not say.', { sanity: -1 })),
    leave: O('You left. The recruit was still getting rule four wrong.') },
], (r) => E('gh_tavern', 'jianghu', { on: 'tavern', if: { loc: r.loc, age: [12, 90], ...(r.if || {}) }, art: 'inn', title: r.title, text: r.text, choices: [
  Q('Buy the talker another cup (1 tael)', { stat: { wealth: '>=1' } }, { ...r.pour, wealth: -1 }), r.press, C('Finish your cup and go', r.leave),
] }));

// Ferries and crossings, as you set out from a river town.
const tplFerry = template('gh_ferry', [
  { key: 'luoyang', loc: 'luoyang', title: 'The Mengjin ferry', text: 'The Mengjin ferry crosses the Yellow River north of {loc}. The ferryman wants five taels, which is four more than yesterday, because it rained.',
    choices: [
      Q('Pay (5 taels)', { stat: { wealth: '>=5' } }, O('You paid. The ferryman sang the whole way across, badly, for free.', { wealth: -5 })),
      R('Swim it', 'body', 36, O('You swam the Yellow River. The ferryman, rowing alongside in case, was so impressed he gave you back your fare, which you had not paid.', { body: 1, fame: 1 }), O('The river swam you, a li downstream, into a bed of reeds.', { health: -12 })),
      C('Wait a day for the price to fall', O('It rose. You paid anyway, plus a day.', { wealth: -6, sanity: -1 })),
    ] },
  { key: 'kaifeng', loc: 'kaifeng', title: 'The pontoon bridge', text: 'Soldiers on the pontoon bridge over the Yellow River below {loc} are stopping every martial artist and asking for papers that do not exist.',
    choices: [
      Q('Pay the bridge fee (3 taels)', { stat: { wealth: '>=3' } }, O('The fee did not exist either. It went into the sergeant’s boot.', { wealth: -3 })),
      R('Bluff your way across', 'insight', 26, O('You produced a laundry receipt with great ceremony. The sergeant could not read. You crossed.', { insight: 1 }), O('The sergeant could read. You paid double for the laundry receipt.', { wealth: -6, rep: { court: -1 } })),
      C('Help a stuck ox-cart across instead', O('You put your shoulder to an ox-cart jammed on the planks. The soldiers, entertained, waved you across with it.', { body: 1, health: -2 })),
    ] },
  { key: 'wuchang', loc: 'wuchang', title: 'The Great River ferry', text: 'The ferry across the Great River at {loc} is packed: farmers, chickens, a monk, a coffin and a bride on her way to be married. Halfway across, the wind rises.',
    choices: [
      R('Help hold the sail', 'body', 28, O('You held the sail with two boatmen while the ferry heeled. The bride laughed the whole way; she said it was a good omen.', { fame: 1, sanity: 3 }), O('The sail got away from you and the coffin went overboard. It floated. Its occupant did not complain.', { sanity: -2, charm: -1 })),
      C('Hold on to the chickens', O('You held on to the chickens. Somebody had to.', { sanity: 2 })),
      Q('Pay for a cabin (2 taels)', { stat: { wealth: '>=2' } }, O('A cabin with a window and a smell of fish. You slept through the storm.', { wealth: -2, health: 2 })),
    ] },
  { key: 'dongting', loc: 'dongting', danger: true, title: 'Crossing the lake', text: 'The fastest way across Lake Dongting is a Water Fortress “ferry,” which is a pirate boat that has agreed, for a fee, not to be one.',
    choices: [
      Q('Pay the pirates (6 taels)', { stat: { wealth: '>=6' } }, O('They took you across with perfect courtesy and a running commentary on which boats they had robbed where.', { wealth: -6, rep: { unorthodox: 1 } })),
      R('Haggle with the captain', 'charm', 28, O('You talked him down to two taels and a song. He sang it himself.', { wealth: -2, charm: 1 }), O('Haggling, he explained, costs extra.', { wealth: -9 })),
      P('Take a fisherman’s boat instead', 0.6, O('The fisherman crossed by night between pirate lanterns without a single word.', { sanity: 2 }), O('Pirates caught the fisherman’s boat in the reeds.', { combat: { foe: { name: 'a reed pirate', kind: 'bandit', rel: 0 }, context: 'ambush', lethal: 0.25, win: { text: 'The pirate went into the reeds. The fisherman refused your money.', fame: 1, rep: { unorthodox: -2 } }, lose: { text: 'They took your purse and the fisherman’s catch, and let you both go.', wealth: -10 } } })),
    ] },
  { key: 'chengdu', loc: 'chengdu', title: 'The chain bridge', text: 'West of {loc} the road crosses a gorge on a bridge of iron chains and loose planks. The wind is playing it like a zither.',
    choices: [
      R('Walk it', 'body', 24, O('You walked it without touching the chains. A porter behind you, carrying a whole pig, did the same and did not seem impressed.', { body: 1, sanity: 1 }), O('You crawled the last third on hands and knees. The porter with the pig stepped over you.', { charm: -1, sanity: -2 })),
      Q('Pay a porter to carry your pack (1 tael)', { stat: { wealth: '>=1' } }, O('He carried your pack, and kindly offered to carry you.', { wealth: -1 })),
      C('Go the long way round', O('The long way took four days and passed the best noodle shop in Shu. No regrets.', { health: 2 })),
    ] },
  { key: 'hangzhou', loc: 'hangzhou', title: 'Between tides', text: 'Leaving {loc}, the ferry over the Qiantang runs only between tides. The ferryman squints at the sky and says you have time, probably.',
    choices: [
      R('Read the tide yourself', 'insight', 22, O('You waited an hour longer than he said. The bore came early, roaring past the empty ferry, and the ferryman bowed to you all the way across.', { insight: 1, sanity: 2 }), O('You trusted your reading. The bore caught the ferry at the far bank and threw everyone into the mud, alive.', { health: -6 })),
      Q('Pay for the fast boat (3 taels)', { stat: { wealth: '>=3' } }, O('Four oarsmen and a drum. You crossed before the tide could think about it.', { wealth: -3 })),
      C('Trust the ferryman', O('He was right, probably, by about the length of a fish.', { sanity: -1 })),
    ] },
  { key: 'changan', loc: 'changan', title: 'The Wei ford', text: 'The Wei River ford outside {loc} is shallow in winter and murderous in summer. A woman with a baby on her back is studying it, deciding.',
    choices: [
      R('Carry them across', 'body', 22, O('You carried them over, the baby giggling at the cold. On the far bank she made you promise to visit her village.', { fame: 1, sanity: 3 }), O('The current took your legs halfway. You got them across and lost your pack.', { wealth: -5, health: -4, fame: 1 })),
      C('Point her to the bridge a day downstream', O('She thanked you and took the long way. So did you. It was a fine day for walking.', { sanity: 1 })),
    ] },
  { key: 'wudang', loc: 'wudang', title: 'Down the Han', text: 'From {loc} the quickest road is a timber raft down the Han, steered by a raftsman who has been drinking since dawn.',
    choices: [
      R('Call the rocks for him', 'insight', 20, O('You called the rocks; he steered, singing. You arrived a day early and slightly in love with rivers.', { sanity: 3, insight: 1 }), O('You called a rock a fish. The raft disagreed with the rock. Everyone swam.', { health: -6 })),
      Q('Pay him to stop drinking (2 taels)', { stat: { wealth: '>=2' } }, O('He stopped. He steered worse sober.', { wealth: -2, charm: 1 })),
      C('Walk the bank', O('You walked the bank for a week and watched the raft pass you on the second day, singing.', { body: 1 })),
    ] },
], (r) => E('gh_ferry', 'jianghu', { on: 'road', if: { loc: r.loc, age: [12, 90] }, once: false, cd: 4, art: 'river', danger: r.danger, title: r.title, text: r.text, choices: r.choices }));

// Escort runs, for those who work as escort guards.
const tplEscort = template('gh_escort', [
  { key: 'luoyang', loc: 'luoyang', title: 'The Kaifeng run', text: 'Pyo Gwang sends a cart of lacquerware to Kaifeng and puts you in charge of the rear. The rear is where things go wrong.',
    main: R('Watch the rear properly', 'insight', 22, O('Two men followed you for a day and gave up when you waved. Pyo Gwang grunted, which from him is a promotion.', { careerUp: 3, wealth: 6, meet: '@escort_chief', rel: { '@escort_chief': { res: 8 } } }), O('You dozed. A box went missing. Pyo Gwang docked it from your pay and said nothing, which was worse.', { wealth: -4, meet: '@escort_chief' })),
    alt: C('Ride up front and chat', O('You rode up front and heard the lacquer merchant’s whole life story, which included three wives and a duel.', { charm: 1, careerUp: 1 })) },
  { key: 'changan', loc: 'changan', title: 'Silk for the west', text: 'A silk caravan bound for the Jade Gate needs guards. The pay is good because the road is bad.',
    main: R('Guard it through the corridor', 'body', 26, O('Six weeks of wind, sand and boredom. Nothing happened, which is what you are paid for.', { careerUp: 3, wealth: 10, health: -3 }), O('Sandstorm, lost camels and a cracked lip that took a season to heal. The merchant paid you half.', { wealth: 4, health: -8 })),
    alt: C('Turn it down', O('The caravan came back with half its guards. You do not ask what happened.', { sanity: -1 })) },
  { key: 'hangzhou', loc: 'hangzhou', title: 'Tea up the Grand Canal', text: 'A barge of first-picking tea goes up the Grand Canal to the capital. Every customs post wants a taste, and a tael.',
    main: R('Handle the customs men', 'charm', 24, O('Eleven customs posts, handled with jokes, flattery and one fake seal. The tea arrived nearly full.', { careerUp: 3, wealth: 8, rep: { merchants: 2 } }), O('By the capital the barge was a third lighter and every customs man between was well supplied.', { wealth: 2, rep: { merchants: -1 } })),
    alt: C('Pay every post its tael', O('You paid. The tea arrived intact, and your wages were mostly customs.', { careerUp: 2, wealth: 2 })) },
  { key: 'chengdu', loc: 'chengdu', title: 'The plank road', text: 'The plank road out of Shu is wooden walkways pinned to the cliffs. Your cart is wider than some of the walkways.',
    main: R('Inch it across on ropes', 'body', 28, O('A rope around the cart and another around you. The cliff got bored before you did.', { careerUp: 3, wealth: 9, body: 1 }), O('A wheel went over. You held the cart while the mule screamed. You saved the cart. The mule never forgave you.', { careerUp: 1, wealth: 3, health: -10 })),
    alt: C('Unload it and carry it in pieces', O('Twelve trips. Your back will remember the plank road for the rest of your life.', { careerUp: 2, wealth: 6, health: -4 })) },
  { key: 'wuchang', loc: 'wuchang', danger: true, title: 'River convoy', text: 'Four boats take cotton downriver from {loc}. On the second night a fast boat with no lantern slides out of the dark toward the last barge.',
    main: C('Meet it with a spear', O('You met it.', { combat: { foe: { name: 'a river raider', kind: 'bandit', rel: 0 }, context: 'ambush', lethal: 0.25, win: { text: 'The raiders went over the side. The convoy master paid you a bonus and told the story at every stop.', careerUp: 4, wealth: 15, fame: 1 }, lose: { text: 'They cut the last barge loose and took it. You were docked for it.', wealth: -5 } } })),
    alt: R('Light every lantern and beat the drums', 'insight', 26, O('The raiders saw four boats awake and lit like a festival and decided to rob someone else.', { careerUp: 2, wealth: 8 }), O('They came anyway, slower. You lost a bale of cotton and nobody died.', { careerUp: 1, wealth: 4 })) },
  { key: 'capital', loc: 'capital', title: 'No questions', text: 'An Eastern Depot officer hires your agency to carry a sealed box out of the capital. The fee is enormous. The instructions: do not open it, do not drop it, do not ask.',
    main: C('Carry it, and do not ask', O('You carried it. You did not ask. When it was delivered, the man who received it wept. You will never know why.', { careerUp: 3, wealth: 20, rep: { court: 3 }, sanity: -3 })),
    alt: R('Open it at night', 'insight', 34, O('Inside: a child’s shoe and a letter of pardon. You resealed it perfectly and delivered it, and wished you had not looked.', { careerUp: 2, wealth: 20, sanity: -2, insight: 2 }), O('The seal broke. You delivered it broken. The officer said nothing at all, and wrote something down.', { wealth: 10, rep: { court: -4 }, flag: 'gh.depot_file' })) },
  { key: 'jadegate', loc: 'jadegate', title: 'Past the red banners', text: 'A western caravan wants escort east from {loc}, past hills where red banners have been seen. The caravan master pays half in advance and keeps looking at the ridges.',
    main: R('Take the old salt road', 'insight', 30, O('The salt road was slow, empty and safe. The caravan master paid the other half and a bonus in raisins.', { careerUp: 3, wealth: 14 }), O('It was not empty. Cult riders watched you from a ridge all day, decided you were not worth it, and rode off. You aged a year.', { careerUp: 2, wealth: 10, sanity: -4 })),
    alt: C('Hire a Cult deserter as a guide', O('He knew every watch post between the Gate and Chang’an. He also stole the raisins.', { careerUp: 2, wealth: 12, rep: { cult: 1 } })) },
  { key: 'kaifeng', loc: 'kaifeng', title: 'Something that ticks', text: 'A Ghost Market broker wants a package carried from {loc} to Luoyang. It is light, wrapped in black cloth, and it ticks.',
    main: R('Carry it without unwrapping it', 'sanity', 45, O('Nine days of ticking. In Luoyang the man unwrapped it: a western water-clock worth a fortune. You were almost disappointed.', { careerUp: 3, wealth: 18 }), O('On the fourth day you could not stand the ticking and threw it into a river. You paid for it for a year.', { wealth: -15, sanity: 2 })),
    alt: C('Refuse the job', O('The broker shrugged and hired someone else, who was never seen again, possibly because he became rich.', { rep: { merchants: -1 } })) },
], (r) => E('gh_escort', 'jianghu', { on: 'work', if: { career: 'escort', loc: r.loc, age: [15, 70] }, once: false, cd: 3, art: 'road', danger: r.danger, title: r.title, text: r.text, choices: [r.main, r.alt] }));

// Famous names met in passing, while wandering near where they live.
const tplPassing = template('gh_passing', [
  { key: 'beggar_chief', npc: 'beggar_chief', loc: 'luoyang', age: [10, 90], text: 'Under a Luoyang bridge a beggar with nine fingers is roasting a chicken in clay. He looks at you, at the chicken, and back. “You look like someone who has never stolen a chicken,” he says. “Sit. It is educational.”',
    a: C('Sit and eat', O('The best chicken of your life. He talked about everything and nothing and asked three questions you are still answering. Only later did someone tell you he was Hong Chil, the Nine-Fingered Beggar, chief of the Beggars’ Sect.', { meet: '@beggar_chief', rel: { '@beggar_chief': { aff: 10 } }, insight: 1, health: 2 })),
    b: R('Offer him wine for the recipe', 'charm', 30, O('He took the wine and gave you the recipe, which was mostly “steal the chicken.” Then he showed you a step, a lurch like a drunk falling, that made you miss him from arm’s length.', { meet: '@beggar_chief', rel: { '@beggar_chief': { res: 10 } }, qi: 5, insight: 2 }), O('He drank the wine and said the recipe was a secret of the Beggars’ Sect, which it is.', { meet: '@beggar_chief', charm: 1 })) },
  { key: 'cheongun', npc: 'cheongun', loc: 'wudang', age: [9, 90], text: 'On a Wudang slope a tiny old Daoist is flying a kite with three children and losing an argument with them about the wind.',
    a: C('Join the argument', O('You sided with the children. The old Daoist conceded gracefully, then lifted one finger, and the kite stood still in the air for a full minute while the children shrieked. “The wind agrees with me,” said Cheong-un.', { meet: '@cheongun', rel: { '@cheongun': { aff: 12 } }, sanity: 4 })),
    b: R('Watch how he holds the string', 'insight', 34, O('He did not hold it. It held itself, a hair above his palm. You did not understand it then. You think about it every time you meditate.', { meet: '@cheongun', qi: 12, insight: 2 }), O('He held it the way an old man holds a kite string.', { meet: '@cheongun', insight: 1 })) },
  { key: 'sweeping_monk', npc: 'sweeping_monk', loc: 'songshan', age: [9, 90], text: 'An old monk is sweeping the steps of the Scripture Pavilion at Shaolin. The leaves he sweeps rise for a moment before they settle on his pile.',
    a: C('Offer to help', O('He handed you the broom. Your leaves went everywhere. He took it back and said, “Again tomorrow,” and was not there tomorrow.', { meet: '@sweeping_monk', body: 1, sanity: 2 })),
    b: R('Watch the leaves', 'insight', 40, O('You watched until dusk. Every sweep was the same sweep. Something in your stance shifted that night and never shifted back.', { meet: '@sweeping_monk', insight: 3, qi: 8 }), O('They were leaves.', { meet: '@sweeping_monk' })),
    c: C('Bow to him', O('You bowed. He bowed back exactly as deep, which no monk at Shaolin had done for you before.', { meet: '@sweeping_monk', rep: { orthodox: 1 }, sanity: 2 })) },
  { key: 'fisherman', npc: 'fisherman', loc: 'dongting', age: [12, 90], text: 'At dawn in the deep channel an old man fishes from a punt with a line and no hook. Fish keep jumping into his basket anyway, as if apologising.',
    a: C('Sit in silence beside him', O('Two hours, and neither of you spoke. When you stood to go he handed you a fish without looking up. It was the best fish of your life.', { meet: '@fisherman', sanity: 5, health: 2 })),
    b: R('Ask him how', 'sanity', 50, O('“Want nothing,” he said, “and the lake gives you everything. It is very simple. Nobody can do it.” For one heartbeat, you could.', { meet: '@fisherman', qi: 10, insight: 1 }), O('“You want the answer too much,” he said, and went back to fishing.', { meet: '@fisherman', sanity: -1 })) },
  { key: 'yakseon', npc: 'yakseon', loc: 'emei', age: [12, 90], text: 'On an Emei herb path an old woman with a basket grabs your wrist, frowns at your pulse and says, “Your liver is a disgrace.”',
    a: C('Ask what to do about it', O('She told you in detail while she picked: no wine, no anger, bitter melon. She gave you a packet of something foul. It worked. Years later someone said the name Yak Seon, the Medicine Immortal, and you remembered the basket.', { meet: '@yakseon', rel: { '@yakseon': { aff: 10 } }, health: 12 })),
    b: R('Ask what she is picking', 'insight', 32, O('She was so pleased somebody asked that she gave you a lesson on the roots of the Emei slopes until dark.', { meet: '@yakseon', insight: 2, recipe: 'heart_calming' }), O('She pointed at a leaf. “Poison,” she said. You stepped back. “Not for you,” she said, and laughed.', { meet: '@yakseon', charm: 1 })) },
  { key: 'paeng_gu', npc: 'paeng_gu', loc: 'paeng', age: [14, 60], text: 'A big young man from the Paeng fortress challenges you to a duel, then to a drink, then to a drinking duel, all in one breath.',
    a: C('Drink', O('You matched Paeng Gu cup for cup until one of you fell over. Nobody remembers which. You woke in the Paeng stables as friends.', { meet: '@paeng_gu', rel: { '@paeng_gu': { aff: 15 } }, health: -3, sanity: 3 })),
    b: C('Duel', O('He grinned and raised his fists.', { meet: '@paeng_gu', combat: { foe: '@paeng_gu', context: 'spar', lethal: 0, win: { text: 'You put him on his back. He laughed so hard he could not get up. “Again,” he said. “Tomorrow. Drinks today.”', rel: { '@paeng_gu': { res: 15 } }, rep: { families: 2 } }, lose: { text: 'He put you on your back, helped you up and bought you a drink, which was nearly worse.', rel: { '@paeng_gu': { aff: 10 } } } } })) },
  { key: 'jegal_ha', npc: 'jegal_ha', loc: 'jegal', age: [12, 60], text: 'In a teahouse near the Jegal Estate a young woman is playing baduk against herself and losing, on purpose, with great concentration.',
    a: C('Ask why she plays to lose', O('“To see how I would beat me,” said Jegal Ha, as if that were obvious. Then she asked about your enemies, and took notes.', { meet: '@jegal_ha', insight: 1, rel: { '@jegal_ha': { res: 5 } } })),
    b: R('Play the losing side for her', 'insight', 38, O('You played her losing side and very nearly won. She looked up in open delight. “Again,” she said. “You are terrible in a new way.”', { meet: '@jegal_ha', rel: { '@jegal_ha': { aff: 12, res: 10 } }, insight: 2 }), O('She beat you in thirty moves while still playing herself on the other board.', { meet: '@jegal_ha', insight: 1 })) },
  { key: 'mountain_tiger', npc: 'mountain_tiger', loc: 'taihang', age: [14, 80], text: 'You stumble on a bandit fire in the Taihang. A huge man in a tiger-skin cloak waves you in before his men can draw. “Guests eat first,” says Ma Hu, the Mountain Tiger. “Rule six.”',
    a: C('Eat', O('Roast boar with forty bandits and their king, who told you about his rules, his mother and the time he robbed a magistrate of his trousers. In the morning his men walked you to the road.', { meet: '@mountain_tiger', rel: { '@mountain_tiger': { aff: 10 } }, rep: { unorthodox: 3 }, codex: 'secret.gh_tiger_code' })),
    b: R('Ask him why he keeps rules', 'charm', 30, O('“Because a bandit without rules is a murderer,” he said, “and murderers get hanged. Bandits get legends.” He let you keep your purse, which is rule one for guests.', { meet: '@mountain_tiger', rel: { '@mountain_tiger': { res: 10 } }, rep: { unorthodox: 2 }, insight: 1 }), O('He thought so long his boar burned. “I forget,” he said at last. “But I keep them.”', { meet: '@mountain_tiger', charm: 1 })) },
  { key: 'merchant_king', npc: 'merchant_king', loc: 'hangzhou', age: [12, 80], text: 'A fat, cheerful man on a West Lake bridge looks you up and down. “I can tell what anyone is worth by their shoes,” he says. “Yours: eleven taels. Want to know how to be worth more?”',
    a: C('Listen', O('An hour on interest, debt, and how every friendship has a price. It was genuinely good advice. You felt like you needed a wash. Geum Man-bok of the Golden Abacus, someone told you later, gives that speech before he ruins people.', { meet: '@merchant_king', insight: 2, rep: { merchants: 1 } })),
    b: R('Tell him what his shoes are worth', 'charm', 32, O('You guessed four hundred taels. He laughed delightedly. “Four hundred and twenty,” he said. “Come and work for me.”', { meet: '@merchant_king', rel: { '@merchant_king': { res: 10 } }, rep: { merchants: 3 } }), O('You were wrong by a factor of ten. He patted your shoulder and walked off, still cheerful.', { meet: '@merchant_king', charm: -1 })) },
  { key: 'ilgak', npc: 'ilgak', loc: 'songshan', age: [10, 40], text: 'A young Shaolin monk sits under a pine eating his fifth steamed bun. He sees you looking at the sixth and offers it to you with enormous reluctance.',
    a: C('Accept', O('Il-gak watched every bite with suffering on his face. When you finished he laughed and said you were the first person who had ever actually taken one. You have been friends since.', { meet: '@ilgak', rel: { '@ilgak': { aff: 15 } }, health: 1 })),
    b: R('Wrestle him for it', 'power', 25, O('You pinned him for a heartbeat. He gave you the bun and asked to spar every day you were at Mount Song.', { meet: '@ilgak', rel: { '@ilgak': { res: 10 } }, body: 1 }), O('It was like wrestling a temple bell. You lost the bun and your dignity and gained a friend.', { meet: '@ilgak', rel: { '@ilgak': { aff: 10 } } })) },
  { key: 'nameless', npc: 'nameless', loc: 'kaifeng', age: [16, 90], text: 'In a Kaifeng teahouse a woman sits down across from you, pours you tea and asks how your day was. You tell her. When she leaves, you realise you cannot describe her face at all.',
    a: C('Drink the tea she poured', O('Excellent tea, and perfectly safe, this time. Under the cup, a black paper slip: “Not today.”', { meet: '@nameless', sanity: -3, insight: 1 })),
    b: R('Follow her', 'insight', 40, O('Three streets, then she turned and smiled at you, a face you will never forget and still cannot describe. “Good,” she said. “Now stop.” You stopped. Nobody sees the face of Nameless, Master of the Blood Shadow Pavilion, twice; you have, once.', { meet: '@nameless', rel: { '@nameless': { res: 15 } }, insight: 2, codex: 'people.nameless' }), O('You followed a woman for three streets. She was a fishmonger. The woman from the teahouse was long gone.', { charm: -1 })) },
], (r) => E('gh_passing', 'jianghu', { on: 'wander', if: { loc: r.loc, alive: r.npc, notMet: r.npc, age: r.age }, text: r.text, choices: [r.a, r.b, ...(r.c ? [r.c] : [])] }));

// Roadside inns, by the region you are leaving.
const tplInn = template('gh_inn', [
  { key: 'guanzhong', region: 'guanzhong', title: 'The inn below Tong Pass', text: 'The inn below Tong Pass is full of soldiers, salt-smugglers and one very old woman who wins every game of dice.',
    a: R('Work out how she wins', 'insight', 28, O('She does not cheat. She just knows when everyone else is cheating. She taught you, for a jar of wine.', { insight: 2, wealth: -2 }), O('You lost five taels working it out. You still have not worked it out.', { wealth: -5 })),
    b: C('Sleep early', O('You slept early and left before dawn, the only guest with all their money.', { health: 2 })) },
  { key: 'central', region: 'central', title: 'Two sects, one inn', text: 'At a crowded inn on the Central Plains, disciples of two rival sects sit at neighbouring tables, comparing the lengths of their swords with their eyes.',
    a: R('Toast both sects', 'charm', 26, O('You raised your cup to both. Neither could refuse without losing face. By midnight they were singing each other’s sect songs, badly.', { charm: 1, rep: { orthodox: 2 } }), O('Both sects heard an insult in your toast. Both left without paying. The innkeeper looked at you.', { wealth: -4 })),
    b: C('Take the table by the door', O('The brawl started at the second watch. You were already outside, finishing your noodles in peace.', { sanity: 1 })) },
  { key: 'jingchu', region: 'jingchu', title: 'The blind singer', text: 'A riverside inn in Jingchu, where boatmen sing and a blind woman plays the pipa for coins. All her songs are about heroes who died young.',
    a: R('Ask about her heroes', 'insight', 24, O('She knew the true version of each. Some, she said, are alive under other names. She named one: an innkeeper upriver who was once a famous saber.', { insight: 2, fame: 1 }), O('She only sang. Some people do not want to be asked.')),
    b: Q('Pay for a happier song (1 tael)', { stat: { wealth: '>=1' } }, O('She played one about a hero who lived to ninety and was very boring. The boatmen booed. You loved it.', { wealth: -1, sanity: 4 })),
    c: C('Sing with the boatmen', O('You sang loudly and badly. The boatmen adopted you for the night.', { charm: 1, sanity: 2 })) },
  { key: 'shu', region: 'shu', title: 'The cliff inn', text: 'On the plank road out of Shu an inn hangs off the cliff on poles. The floor has gaps. Through the gaps: cloud.',
    a: R('Sleep soundly anyway', 'sanity', 40, O('You slept like a baby over the abyss and woke to monkeys on the roof. Only one guest in ten sleeps the first night, the innkeeper said.', { health: 4, sanity: 3 }), O('You lay awake all night listening to the poles creak.', { sanity: -3, health: -2 })),
    b: C('Ask how long it has stood', O('“Two hundred years,” the innkeeper said. “Fell down twice.”', { charm: 1 })) },
  { key: 'jiangnan', region: 'jiangnan', title: 'The last room', text: 'A canal inn in Jiangnan: silk merchants, scholars, and a young master travelling with eleven servants, who has taken every room but one.',
    a: R('Charm the landlady into giving you the last room', 'charm', 28, O('The landlady liked your manners. The young master’s twelfth servant slept in the stable, glaring.', { health: 3, charm: 1 }), O('The young master took the last room too, for his luggage.', { health: -2 })),
    b: C('Share the stable with the twelfth servant', O('He was the young master’s cousin, demoted for gambling. You traded stories all night.', { sanity: 3, rep: { families: 1 } })) },
  { key: 'hebei', region: 'hebei', title: 'An inn with ears', text: 'At an inn on the capital road, the man at the next table has been reading the same page of his book for an hour, his ear turned toward you.',
    a: R('Feed him false gossip', 'insight', 30, O('You told your neighbour, loudly, about a treasure in a well in Henan. Somewhere a Depot report now sends three men to dig.', { insight: 1, sanity: 2 }), O('He wrote down everything you said, including the parts that were true.', { flag: 'gh.depot_file', rep: { court: -1 } })),
    b: C('Talk only about the weather', O('You discussed the weather for three hours. He left in despair.', { charm: 1 })) },
  { key: 'liaodong', region: 'liaodong', title: 'The snow inn', text: 'A snowbound inn in Liaodong: a fire, a pot of mutton and a Moyong courier who has not taken off his gloves in two days.',
    a: R('Ask what he carries', 'charm', 30, O('“Letters,” he said with perfect courtesy, “for people who are about to be surprised.” Then he shared his mutton, which for a Moyong is a confession of deep friendship.', { rep: { families: 2 }, health: 2 }), O('His answer was so perfectly courteous you felt slapped.', { charm: -1 })),
    b: C('Eat the mutton', O('The mutton was the best thing that has ever happened to you in a snowstorm.', { health: 4 })) },
  { key: 'west', region: 'west', title: 'The caravanserai', text: 'A caravanserai at the edge of the desert: camels, bells, eleven languages and one shared well. A western merchant offers to trade you a curved knife for your boots.',
    a: R('Inspect the knife', 'insight', 26, O('The steel was patterned like water. You traded your boots, walked to the next town barefoot and sold the knife for thirty taels.', { wealth: 25, health: -3 }), O('It was patterned like water because it was painted. You kept your boots.')),
    b: C('Ask about the road west', O('He told you about cities of white stone, rivers of sand and a mountain that sings. You could not tell how much was true. All of it, possibly.', { insight: 1, sanity: 2 })) },
], (r) => E('gh_inn', 'jianghu', { on: 'road', if: { region: r.region, age: [12, 90] }, once: false, cd: 5, art: 'inn', title: r.title, text: r.text, choices: [r.a, r.b, ...(r.c ? [r.c] : [])] }));

// Arriving at the gates of the great sects and families.
const tplGate = template('gh_gate', [
  { key: 'mounthua', loc: 'mounthua', art: 'mountain', if: { notSect: 'mounthua' }, title: 'Debt collectors at the gate', text: 'At the Mount Hua gate three debt collectors from Chang’an are arguing with a junior disciple who has nothing to give them but tea.',
    choices: [
      Q('Pay one of the debts (10 taels)', { stat: { wealth: '>=10' } }, O('You paid one debt. The junior stared at you like a ghost. Mount Hua remembered.', { wealth: -10, rep: { orthodox: 4 } })),
      R('Talk the collectors down', 'charm', 26, O('You reminded them, cheerfully, how many swordsmen live on this mountain. They agreed to wait another year.', { rep: { orthodox: 2 }, charm: 1 }), O('They told you whose debt it was: the Sect Leader’s own. You had nothing to say to that.', { sanity: -1 })),
      C('Walk past', O('You walked past. The junior went on pouring tea for men who had come to ruin his sect.')),
    ] },
  { key: 'songshan', loc: 'songshan', art: 'temple', title: 'The gatekeeper’s question', text: 'The gatekeeper monk at Shaolin asks every visitor one question before he lets them in. Yours is: “What did you leave outside?”',
    choices: [
      R('Answer him truly', 'insight', 30, O('You told him. He nodded and stepped aside. “Pick it up on the way out,” he said, “if you still want it.”', { insight: 2, sanity: 3, rep: { orthodox: 1 } }), O('Your answer was clever. He let you in anyway, sighing.', { charm: -1 })),
      C('Say, “Nothing.”', O('“Then you are carrying too much,” he said, and let you in.', { sanity: 1 })),
    ] },
  { key: 'wudang', loc: 'wudang', art: 'mountain', title: 'Stairs or sedan', text: 'At the foot of the Wudang stair a junior Daoist offers visitors a choice: the stairs, which take a day, or a sedan chair, which takes an hour, three taels and the contempt of everyone you pass.',
    choices: [
      R('Take the stairs', 'body', 24, O('A day of stairs. At the top an old Daoist handed you a cup of water and looked at your legs approvingly.', { body: 1, qi: 5 }), O('You took the stairs, and then the sedan chair for the last third. The bearers were very kind about it.', { wealth: -2, charm: -1 })),
      Q('Take the sedan chair (3 taels)', { stat: { wealth: '>=3' } }, O('The bearers ran the whole way up, singing. You arrived feeling like luggage.', { wealth: -3, sanity: 1 })),
    ] },
  { key: 'emei', loc: 'emei', art: 'temple', title: 'Tea at the Golden Summit', text: 'At the Emei gate the nuns serve tea to every pilgrim. Male visitors take theirs at a table outside, under the eye of a swordswoman who does not blink.',
    choices: [
      R('Make the swordswoman smile', 'charm', 28, O('It took an hour. It was a very small smile. Her sisters talked about it for a week.', { charm: 1, rep: { orthodox: 1 } }), O('She did not smile. She did refill your tea, which you chose to count.')),
      C('Drink the tea and admire the clouds', O('The clouds below the Golden Summit rolled like a sea. You drank three cups and forgot why you came.', { sanity: 4 })),
    ] },
  { key: 'kunlun', loc: 'kunlun', art: 'snow', if: { notSect: 'kunlun' }, title: 'The snow gate', text: 'Kunlun’s gate stands in snow to the knee. The gatekeeper looks at you without speaking for a long time, as Kunlun gatekeepers do.',
    choices: [
      R('Stare back', 'sanity', 45, O('You stared until he blinked. He nodded. You suspect it was the first time in years.', { rep: { orthodox: 2 }, sanity: 2 }), O('You blinked, shivered and asked if you could come in. “Yes,” he said. “You could have asked at once.”', { charm: -1 })),
      C('Bow and wait', O('You bowed and waited in the snow. After an hour he brought you hot water and still said nothing.', { health: -3, rep: { orthodox: 1 } })),
    ] },
  { key: 'namgung', loc: 'namgung', art: 'estate', if: { notSect: 'namgung' }, title: 'The Namgung gate', text: 'The Namgung gate guards want your name, your sect, your father’s name, and the reason a person of your quality is approaching a family of theirs.',
    choices: [
      R('Let your name speak for you', 'fame', 25, O('They had heard of you. They bowed, a little, and let you through the side gate, which for the Namgung is a red carpet.', { rep: { families: 2 } }), O('They had not heard of you. They let you wait in the sun until they had.', { sanity: -2 })),
      C('Give your father’s name', O('“Never heard of him,” the guard said, and wrote it down anyway.', { charm: -1 })),
    ] },
  { key: 'dangclan', loc: 'dangclan', art: 'garden', if: { notSect: 'dang' }, title: 'Tea at the Dang gate', text: 'At the outer gate of the Dang Clan Manor a servant offers you tea. Every visitor is offered tea. It is a courtesy, and a test, and possibly not tea.',
    choices: [
      R('Smell it first', 'insight', 30, O('Jasmine, ginger and a faint numbing bitterness. You smiled and drank around it. The servant bowed lower than before.', { rep: { families: 3 }, insight: 1 }), O('You drank it. Your tongue was numb for a day. Harmless, the servant assured you. Mostly.', { health: -5, rep: { families: 1 } })),
      M('Ask for a jade spoon to stir it', 'secret.gh_grey_heart', O('The servant’s eyes widened. She brought the spoon, and a fresh pot, and the steward came out to see who you were.', { rep: { families: 5 }, meet: '@dang_okran' })),
      C('Decline politely', O('“Most do,” she said, smiling. “The ones who drink are fools or friends.”')),
    ] },
  { key: 'paeng', loc: 'paeng', art: 'estate', if: { notSect: 'paeng' }, title: 'The Paeng welcome', text: 'The Paeng fortress gate opens with a roar of laughter and a man the size of a door, who slaps your back so hard you see your ancestors.',
    choices: [
      R('Slap him back', 'body', 26, O('He staggered. The whole gate cheered. You were carried inside on a tide of wine.', { rep: { families: 3 }, fame: 1 }), O('He did not notice.', { health: -3, rep: { families: 1 } })),
      C('Bow', O('You bowed. He bowed back, enormously, and knocked over a lantern.', { charm: 1 })),
    ] },
  { key: 'moyong', loc: 'moyong', art: 'snow', if: { notSect: 'moyong' }, title: 'Moyong courtesy', text: 'At the Moyong gate a steward greets you with a bow precise enough to cut glass, and asks whether you would prefer to be received in the warm hall or the honest one.',
    choices: [
      R('Ask for the honest hall', 'insight', 32, O('Cold, plain, and full of Moyong elders who looked at you with interest for the first time.', { rep: { families: 3 }, insight: 1 }), O('You asked which was which. The steward smiled. Wrong answer.', { rep: { families: -1 } })),
      C('Take the warm hall', O('The warm hall was beautiful. Nobody said one true thing to you in it, beautifully.', { health: 2, sanity: -1 })),
    ] },
  { key: 'tenthousand', loc: 'tenthousand', art: 'demonic', if: { notSect: 'cult' }, danger: true, title: 'The red gate', text: 'At the first gate of the Ten Thousand Mountains, Demon Warriors stop every traveller who is not a believer. “State your business,” says the captain, “and your price.”',
    choices: [
      R('State a business they like', 'charm', 32, O('Trade, you said: salt, needles, news from the east. The captain liked news. You were let in, and watched.', { rep: { cult: 3 } }), O('They did not like your business.', { combat: { foe: { name: 'a Demon Warrior', kind: 'cultist', rel: 0 }, context: 'duel', lethal: 0.2, win: { text: 'You won. The captain, who respects strength above all scripture, let you in himself.', rep: { cult: 4 }, fame: 1 }, lose: { text: 'They threw you down the mountain road, which for them is a kindness.', health: -10, rep: { cult: -2 } } } })),
      Q('Pay the price (10 taels)', { stat: { wealth: '>=10' } }, O('The captain bit the silver and stepped aside. Even the Cult has a toll.', { wealth: -10 })),
    ] },
], (r) => E('gh_gate', 'jianghu', { on: 'arrive', if: { loc: r.loc, age: [12, 90], ...(r.if || {}) }, once: false, cd: 8, art: r.art, danger: r.danger, title: r.title, text: r.text, choices: r.choices }));

// ── Templates: history ────────────────────────────────────────────────
// Aftermaths: the world after history happens, years later, where it happened.
const tplAfter = template('gh_after', [
  { key: 'famine', tl: 'famine', if: { year: [9, 11], region: 'central', age: [6, 90] }, art: 'plague', title: 'The soup-kitchen road', text: 'Famine on the Central Plains. A family of five walks past your door each morning on the way to the soup kitchen, and four each evening coming back.',
    choices: [
      C('Share your rice', O('You shared what you had. They stopped walking past and started sitting at your door. By spring there were eleven of them, and all of them were alive.', { wealth: -5, sanity: 6, fame: 1 })),
      R('Find the father work', 'insight', 24, O('You found him a place hauling dike stones for the magistrate, paid in grain. It was enough.', { fame: 1, sanity: 3 }), O('There was no work. There was no grain. You had nothing to give but company.', { sanity: -4 })),
      C('Look away', O('You looked away. One morning there were only three.', { sanity: -8 })),
    ] },
  { key: 'emperor_dies', tl: 'emperor_dies', if: { year: [7, 15], loc: 'capital', age: [10, 90] }, art: 'palace', title: 'The Depot’s new broom', text: 'With a boy on the throne, the Eastern Depot sweeps the capital clean: beggars, fortune-tellers and anyone who mentions the old Emperor’s will are hauled away in carts.',
    choices: [
      C('Hide a fortune-teller in your lodging', O('He hid under your bed for three days and told your fortune for free. It was a terrible fortune. He apologised.', { sanity: 2, rep: { court: -2 } })),
      R('Find out what the will said', 'insight', 26, O('It named the old Emperor’s nephew in the south, who died of a sudden fever that summer. The Depot rules through a boy because a boy is easy to rule.', { codex: { id: 'secret.gh_old_will', cat: 'secrets', title: 'The old Emperor’s will', text: 'The old Emperor’s will named his nephew in the south as heir. The nephew died of a convenient fever in year 5. Wi Chung-hyeon keeps the original will in his own study.' } }), O('A man you asked was gone the next morning. You stopped asking.', { sanity: -4 })),
    ] },
  { key: 'grain_fleet', tl: 'grain_fleet', if: { year: [13, 16], loc: ['wuchang', 'dongting'], age: [12, 90] }, art: 'ship', title: 'Divers on the river', text: 'Divers from every village on the river are working the wrecks of the grain fleet, hauling up rotten rice and, now and then, the paymaster’s silver.',
    choices: [
      R('Dive the paymaster’s barge', 'body', 30, O('Three dives and bursting lungs, and then a sealed chest of ingots. You kept one share and gave the rest to the village whose boat you borrowed.', { wealth: 20, fame: 2, health: -4 }), O('The current pinned you under a hull. A village boy pulled you out. You owe him your life and a new rope.', { health: -14 })),
      C('Help feed the river villages', O('You carried rotten rice to people who ate it anyway. The Court sent no relief. The Water Fortress, of all people, did.', { sanity: 2, rep: { unorthodox: 2, court: -2 } })),
    ] },
  { key: 'willow_raid', tl: 'willow_raid', if: { year: [16, 40], loc: 'willow', age: [15, 120] }, art: 'grave', title: 'Ash and new grass', text: 'Willow Creek is mostly ash and new grass. Someone has planted a willow in the square where the chief’s house stood. A few families have come back.',
    choices: [
      Q('Pay to rebuild the mill (20 taels)', { stat: { wealth: '>=20' } }, O('The mill turned again in spring. Children came to watch it as if it were a miracle, which in a burned village it is.', { wealth: -20, fame: 3, sanity: 5, flag: 'gh.willow_mill' })),
      C('Tend the graves', O('You cleared the weeds from forty graves and said the names you knew, and some you made up for the ones you did not.', { sanity: 3 })),
      M('Walk the north road the raiders took', 'timeline.willow_raid', O('You walked the north road from the Taihang at dusk, the way they came, and fixed every turn of it in your memory. Next time, you will be waiting at the bend.', { insight: 2, sanity: -2 })),
    ] },
  { key: 'shu_plague_end', tl: 'shu_plague_end', if: { year: [20, 26], loc: 'chengdu', age: [20, 120] }, bind: { x: { age: [8, 12], realm: 0, role: 'acquaintance', aff: 45, romance: false } }, art: 'temple', title: 'The plague orphans', text: 'The plague is over. In the Chengdu temple courtyards, orphans sleep in rows under donated quilts. One of them, {x}, has been watching you practise all morning.',
    choices: [
      C('Take {x.him} as your disciple', O('You took {x.him}. {x.He} learned slowly and laughed easily, and on bad nights woke crying for a mother you never met. You sat with {x.him} until morning.', { meet: 'x', role: { x: 'disciple' }, achieve: 'first_disciple', rel: { x: { aff: 20, res: 15 } }, sanity: 4 })),
      Q('Pay for the orphans’ winter rice (15 taels)', { stat: { wealth: '>=15' } }, O('Fifteen taels fed the courtyard all winter. The temple put your name on a board. You asked them to take it down; they did not.', { wealth: -15, fame: 3 })),
      C('Teach them all a game', O('You taught a hundred orphans a stone-throwing game. For one afternoon the courtyard was loud. It was the best sound in Chengdu.', { sanity: 4, meet: 'x' })),
    ] },
  { key: 'namgung_assassination', tl: 'namgung_assassination', if: { year: [24, 30], loc: 'namgung', alive: 'namgung_jin', age: [14, 90] }, art: 'night', title: 'The heir at midnight', text: 'At midnight, through a gap in the Namgung wall, you see Namgung Jin practising alone in the burned shell of his father’s study: the same cut, over and over, upward, at the roof.',
    choices: [
      C('Speak to him', O('He did not stop. “He never looked up,” he said, to the roof. “Namgung men never look up.” You stood with him until dawn, and he let you.', { meet: '@namgung_jin', rel: { '@namgung_jin': { aff: 15 } }, sanity: -2 })),
      R('Correct his cut', 'insight', 30, O('His wrist turned too early, you said. He stopped, stared, tried it your way. The cut sang. He looked at you as if you were the first person to tell him the truth in a year.', { meet: '@namgung_jin', rel: { '@namgung_jin': { res: 20 } }, insight: 1 }), O('He did not want advice from a stranger peering through a wall, and said so with a roof tile.', { meet: '@namgung_jin', health: -3 })),
    ] },
  { key: 'dang_civil_war', tl: 'dang_civil_war', if: { year: [26, 32], loc: ['dangclan', 'chengdu'], alive: 'dang_min', age: [14, 90] }, art: 'night', title: 'The new patriarch’s hunt', text: 'After the Dang civil war, the new patriarch’s men are hunting the late matriarch’s favourites. One of them, a gentle young man with stained fingers named Dang Min, is hiding in an apothecary’s back room.',
    choices: [
      C('Get him out of Shu', O('You smuggled him out in a cart of medicinal roots. At the border he gave you two jars of salve and a recipe. “For when someone you love is poisoned,” he said. “Because someone will be.”', { meet: '@dang_min', rel: { '@dang_min': { aff: 20 } }, rep: { families: -3 }, item: { healing_salve: 2 } })),
      C('Turn him in', O('The new patriarch paid well. You will remember the way he looked at you.', { wealth: 30, infamy: 3, rep: { families: 3 }, sanity: -8 })),
      C('Leave him be', O('You left him to his hiding. A month later the apothecary burned. Nobody knew if he was inside.', { sanity: -3 })),
    ] },
  { key: 'cult_coup', tl: 'cult_coup', if: { year: [29, 34], loc: 'jadegate', age: [14, 90] }, art: 'desert', title: 'Refugees from the west', text: 'Believers loyal to the murdered Young Heavenly Demon are fleeing the Blood Faction’s purges through the Jade Gate. A mother with a red armband hidden in her sleeve asks you, very quietly, for directions to anywhere.',
    choices: [
      C('Hide her family in your cart', O('You took them east as your “cousins.” The Blood Faction’s riders searched your cart twice and found only cousins.', { rep: { cult: -3 }, sanity: 5, fame: 1 })),
      R('Ask what happened in the Hall', 'insight', 28, O('She told you: the Young Heavenly Demon died at prayer on the first day of spring, through the east door, which somebody had left unbarred.', { codex: 'secret.gh_coup_hall', sanity: -2 }), O('She would not speak of it. Her son would. You wished he had not.', { sanity: -4 })),
      C('Send her to the Beggars’ Sect', O('The Beggars’ Sect will hide anyone from anyone. She went east with a knotted cord for a token.', { rep: { orthodox: 1 } })),
    ] },
  { key: 'alliance_betrayal', tl: 'alliance_betrayal', if: { year: [39, 45], loc: 'luoyang', age: [14, 120] }, art: 'city', title: 'One word', text: 'Someone has painted over Hwangbo Jun’s portrait in the Alliance hall with a single word: “Price.” The Alliance has not had it cleaned. Nobody will admit to being the one who should.',
    choices: [
      C('Clean it', O('You cleaned it, because somebody should. The disciples watching looked ashamed, then helped.', { rep: { orthodox: 3 }, sanity: 1 })),
      C('Add a second word', O('You added “Paid.” By evening there were forty words and a poem, and the Alliance had to close the hall.', { infamy: 1, fame: 2, rep: { orthodox: -2 } })),
      M('Look for the second ledger', 'secret.gh_second_ledger', O('The letters were exposed; the ledger never was. You found it under a floorboard of the empty study and gave it to the Beggars’ Sect, who know what to do with such things.', { rep: { orthodox: 6 }, wealth: 10, fame: 2 })),
    ] },
  { key: 'kunlun_descends', tl: 'kunlun_descends', if: { year: [48, 56], loc: 'luoyang', age: [14, 150] }, art: 'city', title: 'White robes in Luoyang', text: 'Kunlun disciples in white walk Luoyang as if it were a snowfield they intend to cross. Shopkeepers bow. Beggars move. A Kunlun junior kicks over a noodle cart that was in his way.',
    choices: [
      R('Make him apologise', 'fame', 35, O('He apologised, stiffly and publicly, because three other Kunlun juniors were watching to see what you would do next. The noodle seller fed you free for a year.', { fame: 3, rep: { orthodox: -1 } }), O('His senior arrived and made you apologise instead.', { rep: { orthodox: -3 }, sanity: -3 })),
      Q('Pay for the cart (3 taels)', { stat: { wealth: '>=3' } }, O('You paid. The junior watched with puzzled contempt, which you will treasure.', { wealth: -3, sanity: 2 })),
    ] },
  { key: 'depot_coup', tl: 'depot_coup', if: { year: [61, 66], loc: 'capital', age: [16, 150] }, art: 'palace', title: 'A clerk who only copied', text: 'After the failed coup, the Imperial Guard is hunting Depot men through the capital. A clerk with ink-stained hands and no sword begs you to hide him. “I only copied things,” he says. “I only ever copied things.”',
    choices: [
      C('Hide him', O('You hid him in your rafters for a week, then got him out in a coffin cart. He sent a letter from the south, in perfect, beautiful handwriting.', { rep: { court: -3 }, sanity: 3 })),
      C('Hand him over', O('Han Gyeong’s men took him gently. He had a fair trial, as far as you could tell, which in the capital is a great deal.', { rep: { court: 4 }, sanity: -2 })),
      R('Ask what he copied', 'insight', 34, O('Lists. Every murim family in the Registry, and which were marked for “attention.” Yours was there. He told you which page.', { flag: 'gh.registry_list', insight: 2, rep: { court: -1 } }), O('He only shook, and repeated that he copied things.', { sanity: -1 })),
    ] },
  { key: 'shu_quake', tl: 'shu_quake', if: { year: [80, 86], region: 'shu', age: [14, 300], not: 'gh.quake_warned' }, art: 'temple', title: 'Listening for voices', text: 'The earthquake has left Shu in pieces. In a Chengdu street of fallen roofs, people dig with their hands and stop every few minutes to listen for voices.',
    choices: [
      R('Dig', 'body', 30, O('You lifted a beam three men could not. Under it a grandmother sat perfectly calmly, holding a cat. She thanked you and asked for tea.', { fame: 4, health: -6, sanity: 4 }), O('You dug for three days and found no one alive. You kept digging.', { health: -10, sanity: -6 })),
      Q('Buy rice and tents for the street (20 taels)', { stat: { wealth: '>=20' } }, O('Twenty taels of rice and canvas. The whole street slept under your tents all winter.', { wealth: -20, fame: 3 })),
    ] },
  { key: 'saint_last_duel', tl: 'saint_last_duel', if: { year: [50, 60], loc: 'kunlun', age: [14, 300] }, art: 'snow', title: 'A sword in the glacier', text: 'High on the Kunlun glacier, where the Drunken Sword Saint fought his last duel against no one, a sword stands in the ice to the hilt. Around it the ice is cut with a thousand perfect lines.',
    choices: [
      R('Read the lines', 'insight', 44, O('A day and a night. They were not a duel; they were a lesson, left for whoever came. Your sword arm ached with it for a year.', { insight: 3, qi: 15, codex: { id: 'secret.gh_glacier_lines', cat: 'theory', title: 'The glacier lesson', text: 'Around the sword the Sword Saint left in the Kunlun ice, a thousand cuts make a lesson rather than a duel. Read slowly, they teach the last form of his sword.' } }), O('The lines were beautiful, and you did not understand one of them.', { sanity: 1 })),
      R('Draw the sword', 'body', 55, O('It came out of the ice with a sound like a sigh. You held it for one breath, then drove it back in, deeper. Some swords belong where they are.', { fame: 3, insight: 2, sanity: 3 }), O('It did not move. It was never going to move for you. You wonder who it will move for.', { health: -4 })),
      C('Leave a jar of wine beside it', O('You left wine in the snow. On the way down you could have sworn you heard somebody laugh.', { sanity: 4 })),
    ] },
], (r) => E('gh_after', 'timeline', { if: { happened: r.tl, ...r.if }, art: r.art, bind: r.bind, title: r.title, text: r.text, choices: r.choices }));

// Omens: rumours and signs in the years before history happens. Most leave a memory for the next life.
const tplOmen = template('gh_omen', [
  { key: 'shaolin_gates', tl: 'shaolin_gates', if: { year: [5, 6], region: 'central', age: [4, 5] }, art: 'temple', title: 'Smiling monks', text: 'Monks from Mount Song are buying rice in the market and smiling at every child they pass, which is not like them at all.',
    choices: [
      C('Follow them', O('You followed the monks all morning. One finally turned and gave you a steamed bun. “Next spring,” he said, “come and see us.”', { codex: 'timeline.shaolin_gates', health: 1 })),
      C('Ask why they are smiling', O('“Because next spring we open the gate,” the monk said, “and the temple will be full of noise again.”', { codex: 'timeline.shaolin_gates', charm: 1 })),
    ] },
  { key: 'hebei_drought', tl: 'hebei_drought', if: { year: [43, 46], region: 'hebei', age: [14, 200] }, art: 'market', title: 'Late swallows', text: 'The wells of Hebei are low and the old men say the swallows came late. A grain merchant is selling his stock cheap to anyone who will take it before it spoils.',
    choices: [
      Q('Buy his grain (20 taels)', { stat: { wealth: '>=20' } }, O('You filled a cellar. When the rains failed you sold it at fair prices, and the Green Forest found one village fewer full of desperate men.', { wealth: -20, fame: 3, codex: 'timeline.hebei_drought' })),
      M('You remember the drought', 'timeline.hebei_drought', O('You bought every sack and had the villages dig their wells deeper while the ground was still soft. When the drought came, Hebei went hungry, but not as hungry.', { fame: 8, gaze: 1, rep: { court: 3 } })),
      C('Pass', O('You passed. The merchant sold his grain to the Green Forest instead.')),
    ] },
  { key: 'kunlun_descends', tl: 'kunlun_descends', if: { year: [45, 48], loc: ['luoyang', 'kunlun'], age: [14, 200] }, art: 'city', title: 'Measuring the hall', text: 'Kunlun envoys are measuring the Alliance hall in Luoyang with a knotted cord, very carefully, as if deciding where to put their furniture.',
    choices: [
      R('Find out why', 'insight', 30, O('Kunlun means to claim the Alliance, and every sect strong enough to refuse is still burying its war dead.', { codex: 'timeline.kunlun_descends', insight: 1 }), O('The envoys looked at you as if you were weather.')),
      C('Offer to hold the other end of the cord', O('They let you. The hall is forty-four paces long, and Kunlun envoys say nothing at all for forty-four paces.', { charm: 1, rep: { orthodox: 1 } })),
    ] },
  { key: 'registry_edict', tl: 'registry_edict', if: { year: [50, 55], loc: 'capital', alive: 'depot_director', age: [16, 200] }, art: 'palace', title: 'A long document', text: 'In a capital teahouse a Depot scribe is copying a long document with the air of a man who would rather be anywhere else. The heading reads: “On the Registration of the Martial Clans.”',
    choices: [
      R('Read over his shoulder', 'insight', 32, O('Every martial artist, a name and a thumbprint; refusal is outlawry; the Beggars’ Sect to be “examined first.” Already signed: Wi Chung-hyeon.', { codex: 'timeline.registry_edict', insight: 1 }), O('He covered the page with his sleeve and glared.')),
      C('Buy him a drink', O('He drank, sighed, and said only, “In five years you will remember this cup,” which was more than he meant to.', { wealth: -1, codex: 'timeline.registry_edict' })),
      M('Warn the Beggars’ Sect to go underground', 'timeline.beggars_outlawed', O('You took word to Luoyang that the Beggars would be first. They moved their halls into cellars years early, and when the Depot came to burn the bridges there was nobody under them.', { rep: { orthodox: 6 }, gaze: 1, fame: 2 })),
    ] },
  { key: 'depot_coup', tl: 'depot_coup', if: { year: [57, 59], loc: 'capital', flag: 'w.registry', age: [16, 200] }, art: 'palace', title: 'Horses and armour', text: 'The Eastern Depot is buying horses, armour and the loyalty of palace eunuchs, and making no particular secret of any of it.',
    choices: [
      C('Watch the Depot stables', O('You counted horses for a month. Enough for a palace, not a purge.', { codex: 'timeline.depot_coup', insight: 1 })),
      R('Get word to the Imperial Guard', 'charm', 30, O('Han Gyeong received your note, burned it, and doubled the guard on the palace steps.', { meet: '@guard_commander', rel: { '@guard_commander': { res: 10 } }, rep: { court: 2 } }), O('Your note reached the wrong desk. A Depot desk.', { flag: 'gh.depot_file', rep: { court: -4 } })),
    ] },
  { key: 'cult_remnants', tl: 'cult_remnants', if: { year: [62, 66], loc: ['jadegate', 'tenthousand'], happened: 'cult_war', age: [14, 200] }, art: 'desert', title: 'Iron going west', text: 'Smugglers at the Jade Gate are carrying iron west again, a little at a time, and red cloth, a great deal at a time.',
    choices: [
      R('Follow the iron', 'insight', 28, O('To a valley in the Ten Thousand Mountains where boys drill with spears under new banners. The Cult has a new master, and he is patient.', { codex: 'timeline.cult_remnants', rep: { orthodox: 1 } }), O('You lost them in the passes.', { health: -4 })),
      C('Report it at the gate', O('The garrison commander thanked you and filed it with the other reports, in a drawer that no longer closes.', { rep: { court: 1 }, codex: 'timeline.cult_remnants' })),
    ] },
  { key: 'second_war', tl: 'second_war', if: { year: [70, 74], region: ['west', 'guanzhong'], happened: 'cult_war', age: [14, 250] }, art: 'battlefield', title: 'Drums in the hills', text: 'Old soldiers of the first war sit outside a western wine-shop, listening to drums in the hills that nobody else will admit to hearing.',
    choices: [
      C('Listen with them', O('You heard them too. The old soldiers nodded at you as at a comrade. “Again,” one said. “Always again.”', { codex: 'timeline.second_war', sanity: -3 })),
      M('Tell the Alliance what you remember', 'timeline.second_war', O('You gave the Alliance the year, the season and the road. Nobody listened, but Mount Hua and Wudang quietly began to stockpile arrows.', { rep: { orthodox: 4 }, fame: 2 })),
    ] },
  { key: 'red_sky', tl: 'red_sky', if: { year: [88, 90], region: 'guanzhong', age: [14, 300] }, art: 'moon', title: 'The frightened astrologers', text: 'The astrologers of Chang’an are frightened. Something is wrong with the stars over Mount Hua, they say, and they cannot agree on what.',
    choices: [
      C('Touch the bead at your throat', O('The bead was hot as a coal. Whatever the stars are doing, it is doing it too.', { codex: 'timeline.red_sky', sanity: -3, insight: 2 }), { show: { item: 'wheel_bead' } }),
      C('Climb Mount Hua and look', O('From the peak the stars looked ordinary. That was somehow worse.', { codex: 'timeline.red_sky', sanity: 1 })),
    ] },
  { key: 'kunlun_tomb', tl: 'kunlun_tomb', if: { year: [115, 120], loc: 'kunlun', age: [14, 400] }, art: 'snow', title: 'The groaning ice', text: 'The Kunlun glacier groans all night now, like an animal giving birth. The disciples say the mountain is restless. The oldest of them says nothing at all.',
    choices: [
      R('Listen to the ice', 'insight', 40, O('Under the groaning, a rhythm: two notes, over and over, like two hands meeting. Something down there wants to be found.', { codex: 'timeline.kunlun_tomb', insight: 2 }), O('It was ice, groaning.')),
      C('Ask the oldest disciple', O('“My master’s master sealed something in the ice,” he said at last, “and asked us to forget it. We have been very good at forgetting.”', { codex: 'timeline.kunlun_tomb', rep: { orthodox: 1 } })),
    ] },
  { key: 'saint_last_duel', tl: 'saint_last_duel', if: { year: [46, 50], loc: 'kunlun', alive: 'sword_saint', age: [14, 300] }, art: 'snow', title: 'An old man climbing', text: 'An old man with a wine jar is climbing the Kunlun glacier alone, very slowly, a sword on his back. He stops to rest beside you and offers you a drink.',
    choices: [
      C('Drink with him', O('He told you he was going up to fight the only opponent he had never beaten. “Who?” you asked. He tapped his own chest, laughed and climbed on.', { meet: '@sword_saint', rel: { '@sword_saint': { aff: 15 } }, codex: 'timeline.saint_last_duel', sanity: 2 })),
      R('Ask to watch the duel', 'insight', 40, O('He let you watch from a ridge. He fought the wind, the ice and the light. At the end he bowed to nobody, and for a moment you understood what a sword is for.', { meet: '@sword_saint', insight: 4, qi: 10, codex: 'timeline.saint_last_duel' }), O('“No,” he said kindly. “This one is private.”', { meet: '@sword_saint' })),
    ] },
  { key: 'century_assembly', tl: 'century_assembly', if: { year: [96, 99], locType: 'city', age: [14, 400] }, art: 'tournament', title: 'The list of masters', text: 'Alliance runners are reading out, in every city, the names of the living masters who will be invited to the Century Assembly. Crowds gather to listen, and to argue.',
    choices: [
      C('Listen to the list', O('Most of the names belonged to people you had known when they were young and stupid. Some of them still were.', { codex: 'timeline.century_assembly', sanity: 2 })),
      R('Listen for your own name', 'fame', 50, O('It was there. Spelled wrong, but there.', { fame: 2, codex: 'timeline.century_assembly' }), O('It was not. You told yourself you did not care, very convincingly.', { sanity: -2 })),
    ] },
], (r) => E('gh_omen', 'timeline', { if: { timeline: { [r.tl]: 'pending' }, ...r.if }, art: r.art, title: r.title, text: r.text, choices: r.choices }));

// Otherwise: what the world looks like in the years after history was averted.
const tplOtherwise = template('gh_otherwise', [
  { key: 'yellow_flood', if: { averted: 'yellow_flood', region: 'central', year: [8, 14], age: [8, 90] }, art: 'river', title: 'The dikes held', text: 'The Yellow River stayed in its bed. The dike warden who repaired the dikes is being honoured in Kaifeng with a banquet, a plaque and a poem, all praising his foresight.',
    choices: [
      C('Let him have it', O('You let him have it. Thousands of people are alive who will never know why. That is fine. That is the point.', { sanity: 6 })),
      R('Remind him, privately, who shamed him into it', 'charm', 30, O('He went pale, and sent you a gift every New Year for the rest of his life.', { wealth: 10, charm: 1 }), O('He had you thrown out of his own banquet.', { fame: -1 })),
    ] },
  { key: 'old_gu', if: { averted: 'old_gu', alive: 'oldgu', loc: 'luoyang', year: [11, 25], age: [10, 90] }, art: 'moon', title: 'An old man who should be dead', text: 'Old Man Gu is drunk on the shrine steps, as alive as anyone has ever been, singing about a girl from his village sixty years ago. He waves you over.',
    choices: [
      C('Sit and sing with him', O('You sang until the moon went down. He forgot every verse and made up better ones. You thought about the other winter, the one he does not remember, and sang louder.', { rel: { '@oldgu': { aff: 15 } }, sanity: 8 })),
      C('Ask about his secret', O('He tapped his nose. “When I am dead.” Then he looked at you sharply, sober for one breath. “You already know, don’t you?”', { rel: { '@oldgu': { res: 10 } }, insight: 1 })),
    ] },
  { key: 'willow_raid', if: { averted: 'willow_raid', loc: 'willow', year: [15, 30], age: [14, 90] }, art: 'fire', title: 'The night of torches', text: 'Willow Creek has a new festival: every autumn the whole village stands on the north road with torches and pretends to be an army. The children love it. The grown-ups remember why.',
    choices: [
      C('Carry a torch', O('You stood on the north road with your neighbours, shouting at nothing. Nothing came. It was the happiest night of the year.', { sanity: 8, fame: 1 })),
      C('Tell the children what really happened', O('They did not believe you; you made it sound like a story. That is the best thing a massacre can become.', { charm: 1, sanity: 4 })),
    ] },
  { key: 'shu_plague', if: { averted: 'shu_plague', loc: 'chengdu', year: [19, 30], age: [14, 90] }, art: 'market', title: 'Complaining about peppers', text: 'The tanners of Chengdu, moved downriver by the magistrate, curse the busybody who told him to. In the city, a third of the people who would have died are in the market, complaining about the price of peppers.',
    choices: [
      C('Complain about the peppers with them', O('It was the most satisfying complaint of your life.', { sanity: 6 })),
      R('Make peace with the tanners', 'charm', 26, O('You paid for a new well downstream and drank the first cup with them. They still curse you, but fondly.', { wealth: -5, fame: 2 }), O('They threw a hide at you. It was not a clean hide.', { charm: -1 })),
    ] },
  { key: 'namgung_assassination', if: { averted: 'namgung_assassination', loc: 'namgung', alive: 'namgung_hwi', year: [24, 35], age: [16, 90] }, art: 'duel', title: 'The patriarch’s lesson', text: 'Patriarch Namgung Hwi, who in another winter died in his own study, is training alone in the Namgung courtyard at dawn. He sees you watching and beckons with his sword. “You,” he says. “Show me.”',
    choices: [
      C('Show him', O('You stepped into the courtyard.', { meet: '@namgung_hwi', combat: { foe: '@namgung_hwi', context: 'spar', lethal: 0, win: { text: 'You touched his sleeve once with your point. He looked at the cut thread for a long time. “Again,” he said, and you lost every bout after that and learned more than in a year.', rel: { '@namgung_hwi': { res: 20 } }, rep: { families: 4 }, insight: 2 }, lose: { text: 'He put you down three times, gently, explaining each. “You will be good,” he said, “if you live.” From him, that is a blessing.', rel: { '@namgung_hwi': { res: 10 } }, insight: 2 } } })),
      C('Bow and decline', O('“Wise,” he said, and went back to his forms. Namgung pride is real, but so is Namgung respect for people who know their limits.', { meet: '@namgung_hwi', rep: { families: 1 } })),
    ] },
  { key: 'dang_civil_war', if: { averted: 'dang_civil_war', loc: 'dangclan', alive: 'dang_okran', year: [26, 40], age: [16, 90] }, art: 'garden', title: 'Tea with the matriarch', text: 'The Dang matriarch, Dang Ok-ran, who in another spring died of poisoned tea, invites you to tea. She pours it herself, right-handed, watching you with great amusement.',
    choices: [
      R('Drink it without hesitating', 'sanity', 50, O('You drank. She laughed, a dry rustle. “Either you are very brave or you know something,” she said. “I like both.” She sent you home with a Dang token.', { meet: '@dang_okran', rel: { '@dang_okran': { res: 20 } }, rep: { families: 5 } }), O('Your hand shook. She noticed, smiled, and drank from your cup first. “Safe,” she said. “Today.”', { meet: '@dang_okran', rep: { families: 2 } })),
      C('Ask about her second son', O('“Dang Gwang grows orchids now,” she said, “in a very small garden behind a very tall wall. He is very happy. He says so in every letter.”', { meet: '@dang_okran', insight: 1, sanity: -1 })),
    ] },
  { key: 'cult_coup', if: { averted: 'cult_coup', region: 'west', alive: 'haryeong', year: [29, 45], age: [14, 90] }, art: 'library', title: 'A school in the mountains', text: 'In the Ten Thousand Mountains the Young Heavenly Demon has opened a school where Cult children learn letters as well as killing. The Blood Faction’s old officers sneer. The children do not.',
    choices: [
      C('Visit the school', O('Forty children reciting poems in a hall built for executions. A girl of seven corrected your grammar.', { rep: { cult: 3 }, sanity: 5 })),
      R('Ask to teach a lesson', 'charm', 32, O('You taught them a planting song from {home}. Months later you heard sentries singing it on the walls, and Dan Ha-ryeong sent her thanks.', { rep: { cult: 6 }, fame: 1, meet: '@haryeong' }), O('The teacher, a former Demon Warrior, does not let outsiders teach. He did let you sweep.', { rep: { cult: 1 } })),
    ] },
  { key: 'demon_poisoned', if: { averted: 'demon_poisoned', region: 'west', alive: 'old_demon', year: [29, 40], age: [14, 90] }, art: 'market', title: 'An old man buying apricots', text: 'In a western market town an ancient man in plain clothes is buying apricots and haggling badly. His bodyguards, pretending to be porters, are the most frightening men you have ever seen.',
    choices: [
      C('Help him haggle', O('You got him a good price. “I should have died last winter,” he said, apropos of nothing. “Everything tastes better now.” Only later did you learn that the Heavenly Demon, Dokgo Hyeok, buys his own apricots.', { meet: '@old_demon', rel: { '@old_demon': { aff: 10 } }, rep: { cult: 4 } })),
      C('Keep your distance', O('You kept your distance. One of the porters nodded at you, approving.', { insight: 1 })),
    ] },
  { key: 'blood_night', if: { averted: 'blood_night', loc: 'mounthua', year: [34, 50], age: [14, 120] }, art: 'blossom', title: 'Plum blossoms', text: 'Spring on Mount Hua, and the plum trees are flowering over a sect that should be ash. Juniors who should be dead are fighting over whose turn it is to ring the morning bell.',
    choices: [
      C('Ring it for them', O('You rang it. It sounded across the five peaks like a thing that had never been in danger.', { sanity: 10, rep: { orthodox: 3 } })),
      C('Visit the Plum Blossom Path', O('The secret path is walled now and guarded by two bored juniors playing dice. You sat with them and lost three coppers. Worth every one.', { sanity: 6, wealth: -1 })),
    ] },
  { key: 'grain_fleet', if: { averted: 'grain_fleet', flag: 'gh.fleet_warned', loc: ['wuchang', 'dongting'], year: [13, 20], age: [14, 90] }, danger: true, art: 'inn', title: 'The Fortress remembers', text: 'A Water Fortress captain sits down across from you in a river tavern. “You cost us a grain fleet,” he says pleasantly. “The Lord would like to discuss it.”',
    choices: [
      C('Discuss it with your sword', O('He smiled, and stood.', { combat: { foe: { name: 'the Water Fortress captain', kind: 'bandit', rel: 0 }, context: 'duel', lethal: 0.15, win: { text: 'He went through the tavern wall into the river. The Fortress will think twice about discussing things with you.', rep: { unorthodox: -4 }, fame: 3 }, lose: { text: 'He took your purse as the start of the discussion and promised to continue it later.', wealth: -15, rep: { unorthodox: 1 } } } })),
      R('Buy him a drink and talk business', 'charm', 34, O('Two jugs later you had agreed the Fortress would take its revenge on somebody else, for a fee. The fee was reasonable.', { wealth: -10, rep: { unorthodox: 4 } }), O('He drank your wine and told you the Lord does not forget. You did not sleep in the same inn twice for a year.', { wealth: -2, sanity: -4 })),
    ] },
  { key: 'peace_kept', if: { happened: 'peace_kept', loc: 'jadegate', year: [34, 60], age: [14, 120] }, art: 'desert', title: 'Caravans from the west', text: 'Caravans come out of the Ten Thousand Mountains now: wool, iron, medicinal roots, and Cult merchants in red sashes who bargain like anyone else. In another world, this road is a battlefield.',
    choices: [
      C('Trade with them', O('You traded tea for a Cult herbal and got the better of it. The merchant laughed and said you should join the faith; you would make a fine elder.', { wealth: 8, rep: { cult: 3 } })),
      C('Watch the road', O('You watched the caravans for an afternoon and thought about the other road, the one full of the dead. You can never tell anyone how lucky they are.', { sanity: 6, insight: 1 })),
    ] },
  { key: 'registry_edict', if: { averted: 'registry_edict', locType: 'city', year: [55, 65], age: [16, 200] }, art: 'city', title: 'No Registry', text: 'There is no Registry. In the square where the Depot’s desk would have stood, a storyteller is telling the tale of a Director of the Eastern Depot who fell among his chrysanthemums. He tells it as a comedy.',
    choices: [
      C('Laugh with the crowd', O('You laughed. Somewhere, in another world, this square is very quiet. Here it is loud.', { sanity: 5 })),
      C('Tip him to tell it as a tragedy', O('He told it as a tragedy. The crowd wept for a man who would have registered every one of them. People are generous to the dead.', { wealth: -1, insight: 1 })),
    ] },
], (r) => E('gh_otherwise', 'timeline', { if: r.if, art: r.art, danger: r.danger, title: r.title, text: r.text, choices: r.choices }));

export default [...GANGHO, ...HISTORY, ...tplCity, ...tplTavern, ...tplFerry, ...tplEscort, ...tplPassing, ...tplInn, ...tplGate, ...tplAfter, ...tplOmen, ...tplOtherwise];
